    ConceitoPortugues(414, 'vogal aberta', 'Vogal aberta é vogal realizada com maior abertura relativa do trato oral.', 'Ajuda a distinguir timbres vocálicos.', ('vogal', 'articulação'), 'A distribuição exata varia entre variedades.', 'fonetica_fonologia', ('é em pé',), ('Não é o mesmo que sílaba tônica.',)),
    ConceitoPortugues(415, 'vogal fechada', 'Vogal fechada é vogal realizada com menor abertura relativa do trato oral.', 'Contrasta timbres e apoia relações entre fala e acento gráfico.', ('vogal aberta', 'articulação'), 'A distribuição exata varia entre variedades.', 'fonetica_fonologia', ('ê em você',), ('Não significa ausência de som.',)),
    ConceitoPortugues(416, 'vogal tônica', 'Vogal tônica é vogal situada no núcleo da sílaba que recebe maior proeminência na palavra.', 'Liga qualidade vocálica a tonicidade.', ('vogal', 'sílaba tônica', 'núcleo silábico'), '', 'fonetica_fonologia', ('a de casa',), ('Não é necessariamente acentuada graficamente.',)),
    ConceitoPortugues(417, 'vogal átona', 'Vogal átona é vogal situada em sílaba sem a proeminência principal da palavra.', 'Permite observar redução e variação de realização.', ('vogal tônica', 'tonicidade'), 'A redução depende da variedade e da posição.', 'fonetica_fonologia', ('a final de casa',), ('Não é vogal sem som.',)),
    ConceitoPortugues(418, 'consoante surda', 'Consoante surda é consoante produzida sem vibração laríngea funcional durante o segmento.', 'Distingue pares por vozeamento.', ('consoante', 'vozeamento', 'fonema'), '', 'fonetica_fonologia', ('p em pato',), ('Não significa ausência de corrente de ar.',)),
    ConceitoPortugues(419, 'consoante sonora', 'Consoante sonora é consoante produzida com vibração laríngea funcional durante o segmento.', 'Contrasta com consoante surda.', ('consoante surda', 'vozeamento'), '', 'fonetica_fonologia', ('b em bato',), ('Não significa maior volume.',)),
    ConceitoPortugues(420, 'bilabial', 'Bilabial é articulação produzida com participação dos dois lábios.', 'Classifica consoantes por ponto de articulação.', ('ponto de articulação', 'articulação'), '', 'fonetica_fonologia', ('p, b, m',), ('Não é modo de articulação.',)),
    ConceitoPortugues(421, 'labiodental', 'Labiodental é articulação produzida entre lábio inferior e dentes superiores.', 'Classifica parte das fricativas.', ('ponto de articulação', 'articulação'), '', 'fonetica_fonologia', ('f, v',), ('Não é dental.',)),
    ConceitoPortugues(422, 'dental', 'Dental é articulação produzida com aproximação ou contacto da língua junto aos dentes.', 'Permite localizar realizações consonantais.', ('ponto de articulação', 'articulação'), 'A fronteira dental–alveolar varia entre descrições e variedades.', 'fonetica_fonologia', ('Em "tato", o som representado por "t" é uma consoante dental: a língua se aproxima dos dentes.',), ('A realização concreta pode ser alveolar em certas variedades.',)),
    ConceitoPortugues(423, 'alveolar', 'Alveolar é articulação produzida junto à região alveolar atrás dos dentes superiores.', 'Classifica consoantes por localização articulatória.', ('dental', 'ponto de articulação'), 'Realizações variam entre variedades.', 'fonetica_fonologia', ('s em muitas variedades',), ('Não é uma letra específica.',)),
    ConceitoPortugues(424, 'palatal', 'Palatal é articulação produzida pela aproximação da língua ao palato duro.', 'Ajuda a classificar sons como os associados a nh e lh em muitas descrições.', ('ponto de articulação', 'articulação'), 'Há variação fonética entre comunidades.', 'fonetica_fonologia', ('nh, lh',), ('Grafia e realização não são idênticas.',)),
