    ConceitoPortugues(437, 'acento em hiato', 'Acento em hiato é marca usada em certas vogais tônicas que formam sílaba própria após outra vogal.', 'Relaciona hiato, tonicidade e ortografia.', ('hiato', 'sílaba tônica', 'acentuação gráfica'), 'Exceções por contexto gráfico ainda precisam de regras testadas.', 'ortografia', ('saída, baú',), ('Nem todo hiato recebe acento.',)),
