    ConceitoPortugues(472, 'futuro do conjuntivo', 'Futuro do conjuntivo apresenta condição ou eventualidade futura dependente de outra construção.', 'Materializa relação entre futuro e subordinação.', ('conjuntivo', 'futuro', 'subordinação temporal', 'subordinação condicional'), '', 'morfologia_lexico', ('quando estudar, compreenderá',), ('Não é o futuro do indicativo.',)),
    ConceitoPortugues(473, 'oração principal', 'Oração principal é oração que serve de base sintática ou discursiva para uma oração subordinada.', 'Permite localizar dependência sem afirmar independência absoluta de sentido.', ('oração', 'subordinação', 'período composto'), '', 'sintaxe', ('Espero que venhas: espero é a oração principal.',), ('Principal não significa sempre mais importante no conteúdo.',)),
    ConceitoPortugues(474, 'oração reduzida', 'Oração reduzida é oração dependente construída com forma nominal do verbo e sem conectivo finito explícito típico.', 'Reúne formas reduzidas de infinitivo, gerúndio e particípio.', ('oração subordinada', 'infinitivo', 'gerúndio', 'particípio'), '', 'sintaxe', ('Ao chegar, telefonou.',), ('Reduzida não significa incompleta.',)),
    ConceitoPortugues(475, 'oração reduzida de infinitivo', 'Oração reduzida de infinitivo tem verbo no infinitivo e função subordinada no período.', 'Permite analisar dependência sem verbo finito.', ('oração reduzida', 'infinitivo'), '', 'sintaxe', ('É necessário estudar.',), ('Nem todo infinitivo forma oração autônoma.',)),
    ConceitoPortugues(476, 'oração reduzida de gerúndio', 'Oração reduzida de gerúndio tem verbo no gerúndio e expressa relação circunstancial ou descritiva.', 'Liga forma verbal a função subordinada.', ('oração reduzida', 'gerúndio'), '', 'sintaxe', ('Estudando, aprenderás.',), ('A relação semântica precisa do contexto.',)),
    ConceitoPortugues(477, 'oração reduzida de particípio', 'Oração reduzida de particípio tem verbo no particípio e expressa estado resultante ou relação circunstancial.', 'Materializa uma forma de redução oracional.', ('oração reduzida', 'particípio'), '', 'sintaxe', ('Terminada a tarefa, saiu.',), ('Nem todo particípio constitui oração.',)),
    ConceitoPortugues(478, 'oração subordinada substantiva subjetiva', 'Oração subordinada substantiva subjetiva ocupa função de sujeito em relação à oração principal.', 'Liga oração a função nominal de sujeito.', ('oração subordinada substantiva', 'sujeito', 'oração principal'), '', 'sintaxe', ('É necessário que estudes.',), ('Não é oração adjetiva.',)),
    ConceitoPortugues(479, 'oração subordinada substantiva objetiva direta', 'Oração subordinada substantiva objetiva direta ocupa função de objeto direto de um verbo da oração principal.', 'Aplica transitividade direta a uma oração inteira.', ('oração subordinada substantiva', 'objeto direto', 'oração principal'), '', 'sintaxe', ('Desejo que venhas.',), ('Não exige preposição regida.',)),
    ConceitoPortugues(480, 'oração subordinada substantiva objetiva indireta', 'Oração subordinada substantiva objetiva indireta ocupa função de objeto indireto exigido por verbo da oração principal.', 'Aplica regência verbal a uma oração inteira.', ('oração subordinada substantiva', 'objeto indireto', 'oração principal'), '', 'sintaxe', ('Lembro-me de que chegaste.',), ('A preposição depende da regência.',)),
    ConceitoPortugues(481, 'oração subordinada substantiva completiva nominal', 'Oração subordinada substantiva completiva nominal completa sentido de um nome, adjetivo ou advérbio da oração principal.', 'Aplica complemento nominal a uma oração.', ('oração subordinada substantiva', 'complemento nominal', 'oração principal'), '', 'sintaxe', ('Tenho certeza de que virá.',), ('Não completa diretamente um verbo.',)),
    ConceitoPortugues(482, 'oração subordinada substantiva predicativa', 'Oração subordinada substantiva predicativa ocupa função de predicativo em construção com verbo de ligação.', 'Liga oração a predicado nominal.', ('oração subordinada substantiva', 'predicativo do sujeito', 'verbo de ligação'), '', 'sintaxe', ('A verdade é que estudou.',), ('Não é oração subjetiva.',)),
    ConceitoPortugues(483, 'oração subordinada substantiva apositiva', 'Oração subordinada substantiva apositiva explica ou desenvolve um termo anterior como aposto.', 'Liga oração a função explicativa nominal.', ('oração subordinada substantiva', 'aposto'), '', 'sintaxe', ('Só desejo isto: que estudes.',), ('Não é simples citação.',)),
    ConceitoPortugues(484, 'adjunto adverbial de tempo', 'Adjunto adverbial de tempo situa ocorrência em relação temporal.', 'Especializa a função circunstancial do adjunto adverbial.', ('adjunto adverbial', 'tempo verbal'), '', 'sintaxe', ('Estudo hoje.',), ('Tempo sintático não é apenas tempo verbal.',)),
    ConceitoPortugues(485, 'adjunto adverbial de lugar', 'Adjunto adverbial de lugar situa ocorrência ou referência no espaço.', 'Especializa relação locativa.', ('adjunto adverbial', 'advérbio de lugar', 'localização semântica'), '', 'sintaxe', ('Estudo em casa.',), ('Pode ser expresso por sintagma preposicional.',)),
    ConceitoPortugues(486, 'adjunto adverbial de modo', 'Adjunto adverbial de modo caracteriza como uma ocorrência se realiza.', 'Especializa circunstância modal de ação.', ('adjunto adverbial', 'advérbio de modo'), '', 'sintaxe', ('Falou claramente.',), ('Não é o mesmo que modo verbal.',)),
    ConceitoPortugues(487, 'adjunto adverbial de causa', 'Adjunto adverbial de causa apresenta motivo associado à ocorrência.', 'Liga circunstância sintática a papel causal.', ('adjunto adverbial', 'subordinação causal'), '', 'sintaxe', ('Tremeu de frio.',), ('Causa inferida precisa de contexto.',)),
    ConceitoPortugues(488, 'ambiguidade lexical', 'Ambiguidade lexical ocorre quando uma palavra ou forma admite mais de uma leitura relevante no contexto.', 'Especializa polissemia e homonímia na interpretação.', ('ambiguidade', 'polissemia', 'homonímia'), '', 'semantica_pragmatica', ('banco pode indicar assento ou instituição',), ('Não é necessariamente erro.',)),
    ConceitoPortugues(489, 'ambiguidade estrutural', 'Ambiguidade estrutural ocorre quando a organização sintática permite mais de uma relação entre os mesmos elementos.', 'Distingue problema de estrutura de multiplicidade lexical.', ('ambiguidade', 'sintagma', 'oração'), '', 'semantica_pragmatica', ('vi o homem com o telescópio',), ('Não depende obrigatoriamente de palavra polissêmica.',)),
    ConceitoPortugues(490, 'acarretamento', 'Acarretamento é relação em que a verdade de um enunciado exige a verdade de outro em uma interpretação controlada.', 'Permite testar consequência semântica.', ('afirmação', 'inferência', 'relação'), 'Depende de sentidos estabilizados e escopo explícito.', 'semantica_pragmatica', ('João corre acarreta João se move.',), ('Não é simples associação provável.',)),
    ConceitoPortugues(491, 'contradição semântica', 'Contradição semântica ocorre quando duas leituras afirmadas sob o mesmo escopo não podem ser verdadeiras juntas.', 'Ajuda a detectar incompatibilidade de sentido.', ('negação', 'afirmação', 'acarretamento'), '', 'semantica_pragmatica', ('Está vivo e não está vivo no mesmo sentido e tempo.',), ('Diferença de contexto pode desfazer aparente contradição.',)),
    ConceitoPortugues(492, 'ato assertivo', 'Ato assertivo compromete o enunciador com uma descrição, afirmação ou avaliação apresentada como sustentada.', 'Especializa atos de fala de informar e afirmar.', ('ato de fala', 'afirmação'), '', 'semantica_pragmatica', ('A porta está aberta.',), ('Pode ser falso sem deixar de ser assertivo.',)),
    ConceitoPortugues(493, 'ato diretivo', 'Ato diretivo procura levar o interlocutor a realizar uma ação.', 'Reúne pedido, ordem, conselho e convite por função comunicativa.', ('ato de fala', 'intenção comunicativa'), '', 'semantica_pragmatica', ('Por favor, sente-se.',), ('Forma interrogativa pode realizar pedido.',)),
    ConceitoPortugues(494, 'ato compromissivo', 'Ato compromissivo vincula o enunciador a uma ação futura ou responsabilidade.', 'Explica promessas, ofertas e compromissos.', ('ato de fala', 'futuro', 'pessoa gramatical'), '', 'semantica_pragmatica', ('Prometo concluir.',), ('Não é previsão neutra.',)),
    ConceitoPortugues(495, 'ato expressivo', 'Ato expressivo manifesta avaliação, sentimento ou reação do enunciador diante de uma situação.', 'Explica agradecimento, desculpa, felicitação e lamento.', ('ato de fala', 'exclamação', 'contexto'), '', 'semantica_pragmatica', ('Obrigado pela ajuda.',), ('Não se reduz a interjeição.',)),
    ConceitoPortugues(496, 'ato declarativo', 'Ato declarativo produz mudança institucional quando realizado por pessoa, contexto e procedimento reconhecidos.', 'Mostra que certos enunciados fazem algo por convenção social.', ('ato de fala', 'contexto', 'registro'), '', 'semantica_pragmatica', ('Declaro aberta a sessão.',), ('Sem autoridade e contexto adequados, a mudança pode não ocorrer.',)),
    ConceitoPortugues(497, 'alternância de código', 'Alternância de código é mudança entre línguas ou variedades dentro da mesma interação.', 'Descreve prática de falantes bilíngues sem tratá-la automaticamente como falha.', ('bilinguismo', 'contexto', 'registro'), 'Funções sociais concretas dependem da comunidade.', 'variacao_letramento', ('Um falante bilíngue que diz "Vou ao mercado, but primeiro preciso terminar isso" está alternando entre português e inglês.',), ('Não é mistura aleatória obrigatória.',)),
    ConceitoPortugues(498, 'contacto linguístico', 'Contacto linguístico é convivência entre línguas ou variedades que possibilita influência mútua.', 'Liga empréstimo, bilinguismo, alternância e mudança.', ('bilinguismo', 'empréstimo linguístico', 'variação linguística'), 'Efeitos concretos exigem história e observação comunitária.', 'variacao_letramento', ('O português brasileiro tem palavras de origem tupi ("caju", "jacaré") por causa do contacto linguístico com povos indígenas.',), ('Não implica desaparecimento de uma língua.',)),
    ConceitoPortugues(499, 'diglossia', 'Diglossia é distribuição social relativamente estável de variedades ou línguas por funções e contextos diferentes.', 'Distingue domínio funcional de simples diferença individual de estilo.', ('contacto linguístico', 'registro', 'variação situacional'), 'Configurações concretas dependem da comunidade.', 'variacao_letramento', ('Em algumas comunidades, usa-se uma variedade em casa e outra, mais formal, na escola: diglossia.',), ('Não é sinónimo de bilinguismo individual.',)),
    ConceitoPortugues(500, 'equivalência tradutória', 'Equivalência tradutória é relação construída entre segmentos de línguas diferentes que preservam função relevante em determinado contexto.', 'Fornece critério para tradução sem exigir identidade formal.', ('tradução', 'intenção comunicativa', 'contexto'), 'Exige conhecimento suficiente das duas línguas e do contexto.', 'texto_discurso', ('"cross my fingers" em inglês equivale a "fazer figa" em português: expressões diferentes com função equivalente entre as línguas.',), ('Equivalência não é igualdade absoluta.',)),
    ConceitoPortugues(501, 'numeral multiplicativo', 'Numeral multiplicativo expressa multiplicação de quantidade.', 'Completa família funcional de numerais.', ('numeral', 'numeral cardinal'), '', 'classes_funcionais', ('dobro, triplo',), ('Não é numeral cardinal.',)),
    ConceitoPortugues(502, 'numeral fracionário', 'Numeral fracionário expressa divisão de uma unidade em partes.', 'Liga quantidade linguística a fração.', ('numeral', 'numeral cardinal'), '', 'classes_funcionais', ('meio, um terço',), ('Não é numeral ordinal.',)),
    ConceitoPortugues(503, 'numeral coletivo', 'Numeral coletivo expressa quantidade organizada como conjunto convencional.', 'Distingue grupo nomeado de contagem isolada.', ('numeral', 'numeral cardinal'), '', 'classes_funcionais', ('dúzia, centena',), ('Nem todo substantivo coletivo é numeral coletivo.',)),
    ConceitoPortugues(504, 'locução adverbial', 'Locução adverbial é combinação estável que desempenha função de advérbio.', 'Permite reconhecer função acima da palavra isolada.', ('locução', 'advérbio'), '', 'classes_funcionais', ('de manhã, com cuidado',), ('Nem todo sintagma preposicional é locução fixa.',)),
    ConceitoPortugues(505, 'locução conjuntiva', 'Locução conjuntiva é combinação estável que liga orações ou termos com função de conjunção.', 'Amplia conectivos além de uma palavra.', ('locução', 'conjunção', 'conectivo'), '', 'classes_funcionais', ('ainda que, visto que',), ('A relação depende da construção completa.',)),
    ConceitoPortugues(506, 'locução adjetiva', 'Locução adjetiva é combinação que atribui característica a nome como um adjetivo.', 'Liga sintagma preposicional a função qualificadora.', ('locução', 'adjetivo', 'sintagma nominal'), '', 'classes_funcionais', ('amor de mãe',), ('Nem toda expressão com de é locução adjetiva.',)),
    ConceitoPortugues(507, 'locução substantiva', 'Locução substantiva é combinação estável que funciona como unidade nominal.', 'Permite reconhecer nomes compostos por várias palavras.', ('locução', 'nome', 'sintagma nominal'), '', 'classes_funcionais', ('fim de semana',), ('Estabilidade lexical precisa de uso repetido.',)),
    ConceitoPortugues(508, 'locução interjetiva', 'Locução interjetiva é combinação estável com função expressiva ou apelativa semelhante a interjeição.', 'Amplia a classe interjetiva para unidades multipalavra.', ('locução', 'interjeição', 'ato expressivo'), '', 'classes_funcionais', ('meu Deus!',), ('A interpretação depende de contexto e entoação.',)),
    ConceitoPortugues(509, 'preposição essencial', 'Preposição essencial é palavra cuja função básica no sistema é estabelecer relação preposicional.', 'Distingue núcleo da classe de usos ocasionais de outras classes.', ('preposição', 'classe gramatical'), '', 'classes_funcionais', ('a, de, em, por',), ('Inventários normativos podem variar na classificação.',)),
    ConceitoPortugues(510, 'preposição acidental', 'Preposição acidental é palavra de outra origem categorial usada em certo contexto com função preposicional.', 'Mostra que função e classe histórica podem divergir.', ('preposição essencial', 'uso', 'contexto'), '', 'classes_funcionais', ('conforme, durante, exceto',), ('A classificação depende da construção concreta.',)),
    ConceitoPortugues(511, 'oração coordenada sindética', 'Oração coordenada sindética liga-se a outra por conectivo explícito.', 'Distingue coordenação com marca formal.', ('oração coordenada', 'conjunção coordenativa'), '', 'relacoes_oracionais', ('Estudou e aprendeu.',), ('O conectivo pode ter mais de um valor contextual.',)),
    ConceitoPortugues(512, 'oração coordenada assindética', 'Oração coordenada assindética liga-se a outra sem conjunção explícita, usando justaposição e pontuação.', 'Explica coordenação sem conectivo lexical.', ('oração coordenada', 'pontuação'), '', 'relacoes_oracionais', ('Cheguei, vi, venci.',), ('Ausência de conjunção não elimina relação.',)),
    ConceitoPortugues(513, 'oração subordinada desenvolvida', 'Oração subordinada desenvolvida apresenta verbo finito e normalmente conectivo ou relativo explícito.', 'Contrasta com oração reduzida.', ('oração subordinada', 'oração reduzida', 'conjunção subordinativa'), '', 'relacoes_oracionais', ('Espero que venhas.',), ('Nem toda oração finita é subordinada.',)),
    ConceitoPortugues(514, 'período simples', 'Período simples contém uma oração no recorte sintático adotado.', 'Distingue período simples de período composto.', ('período', 'oração'), '', 'sintaxe', ('A criança estuda.',), ('Locuções verbais não criam automaticamente duas orações.',)),
    ConceitoPortugues(515, 'frase nominal', 'Frase nominal é frase sem verbo explícito, mas com função comunicativa completa no contexto.', 'Impede identificar toda frase com oração verbal.', ('frase', 'nome', 'contexto'), '', 'sintaxe', ('Que beleza!',), ('Não é oração no critério verbal tradicional.',)),
    ConceitoPortugues(516, 'frase verbal', 'Frase verbal é frase organizada com verbo explícito ou locução verbal.', 'Relaciona frase e oração sem torná-las idênticas em todos os casos.', ('frase', 'verbo', 'oração'), '', 'sintaxe', ('A criança estuda.',), ('Uma frase pode conter mais de uma oração.',)),
    ConceitoPortugues(517, 'coesão lexical', 'Coesão lexical é continuidade textual construída por repetição, substituição e relações de sentido entre palavras.', 'Complementa coesão referencial e sequencial.', ('coesão', 'campo lexical', 'cadeia referencial'), '', 'texto_discurso', ('casa... moradia... edifício',), ('Sem coerência, repetição lexical isolada não basta.',)),
    ConceitoPortugues(518, 'repetição lexical', 'Repetição lexical retoma a mesma palavra ou radical para manter tema, ênfase ou precisão.', 'Materializa um mecanismo básico de coesão lexical.', ('coesão lexical', 'retomada', 'radical'), '', 'texto_discurso', ('O estudo exige tempo. O estudo exige prática.',), ('Repetição pode ser necessária ou excessiva conforme função.',)),
    ConceitoPortugues(519, 'substituição lexical', 'Substituição lexical retoma referência por palavra de sentido relacionado ou expressão equivalente.', 'Evita repetição mantendo cadeia temática.', ('coesão lexical', 'sinonímia', 'hiperonímia', 'retomada'), '', 'texto_discurso', ('o cão... o animal',), ('A substituição precisa conservar o referente.',)),
    ConceitoPortugues(520, 'paralelismo sintático', 'Paralelismo sintático repete ou alinha estruturas gramaticais equivalentes em sequência.', 'Aumenta clareza, ritmo e comparabilidade textual.', ('sintagma', 'coordenação', 'estilo'), '', 'texto_discurso', ('estudar com método, testar com rigor e escrever com clareza',), ('Não exige palavras idênticas.',)),
    ConceitoPortugues(521, 'sequência de fonemas', 'Sequência de fonemas é uma ordem explícita de unidades fonológicas tratadas como cadeia.', 'Permite analisar combinações sem confundir som, letra e palavra.', ('fonema', 'combinação'), '', 'fonetica_fonologia', ('/p/ + /r/ + /a/',), ('Não é sequência de letras por necessidade.',)),
    ConceitoPortugues(522, 'foco informacional', 'Foco informacional é a parte do enunciado apresentada como informação selecionada, nova ou contrastiva.', 'Liga estrutura informacional, prosódia e ordem.', ('informação nova', 'enunciado', 'contexto'), 'A identificação depende de contexto e não deve ser adivinhada.', 'semantica_pragmatica', ('Foi O LIVRO que ela leu.',), ('Não é sinónimo de tópico.',)),
    ConceitoPortugues(523, 'enumeração', 'Enumeração é organização de duas ou mais unidades em série reconhecível.', 'Sustenta listas, coordenação e pontuação.', ('relação', 'texto'), '', 'texto_discurso', ('pão, água e fruta',), ('Não é simples repetição.',)),
    ConceitoPortugues(524, 'paradigma', 'Paradigma é conjunto organizado de formas relacionadas por posições e contrastes de uma mesma unidade ou classe.', 'Permite construir flexão e irregularidade por comparação interna.', ('relação', 'forma lexical', 'flexão'), 'O paradigma completo de cada classe ainda precisa ser materializado.', 'morfologia_lexico', ('canto, cantas, canta...',), ('Não é lista sem relações.',)),
    ConceitoPortugues(525, 'oposição', 'Oposição é relação em que duas unidades se distinguem por propriedade relevante num domínio.', 'Generaliza contrastes fonológicos, morfológicos e semânticos.', ('diferença', 'relação'), '', 'metalinguagem', ('singular / plural',), ('Não é conflito social.',)),
    ConceitoPortugues(526, 'variante', 'Variante é uma forma alternativa relacionada a outra dentro de um sistema, contexto ou comunidade explicitada.', 'Permite registrar diferença sem duplicar conceito canónico.', ('variação linguística', 'forma lexical'), 'A distribuição de cada variante precisa de contexto.', 'variacao_letramento', ('duas formas usadas em contextos diferentes',), ('Não é erro por definição.',)),
    ConceitoPortugues(527, 'segmentação', 'Segmentação é operação de separar uma cadeia em unidades segundo critérios explícitos.', 'Fornece base comum para segmentação sonora, gráfica, morfológica e textual.', ('diferença', 'combinação'), 'O resultado depende do nível e do critério.', 'metalinguagem', ('texto → frases → palavras',), ('Não é cortar arbitrariamente.',)),
    ConceitoPortugues(528, 'ordem', 'Ordem é relação que posiciona unidades antes, depois ou em hierarquia definida.', 'Sustenta sequência, sintaxe, narrativa e procedimento.', ('relação', 'diferença'), '', 'metalinguagem', ('A antes de B',), ('Não é valor moral.',)),
    ConceitoPortugues(529, 'existência', 'Existência é a apresentação de uma entidade ou situação como pertencente ao domínio considerado.', 'Apoia construções existenciais e quantificação.', ('referência', 'afirmação'), 'Existência no discurso não prova existência no mundo externo.', 'semantica_pragmatica', ('Há um livro na mesa.',), ('Não é posse.',)),
    ConceitoPortugues(530, 'estrutura informacional', 'Estrutura informacional é a organização do enunciado em tópico, foco, informação dada e informação nova.', 'Liga forma, prosódia e contexto discursivo.', ('tópico discursivo', 'informação dada', 'informação nova', 'contexto'), '', 'semantica_pragmatica', ('tema conhecido + informação nova',), ('Não é estrutura sintática completa.',)),
    ConceitoPortugues(531, 'sintaxe', 'Sintaxe é o conhecimento das combinações e dependências entre palavras, sintagmas e orações.', 'Integra constituintes, funções e ordem sem depender de aula pronta.', ('gramática', 'relação', 'oração', 'sintagma'), '', 'sintaxe', ('sujeito + predicado',), ('Não é apenas ordem linear.',)),
    ConceitoPortugues(532, 'situação', 'Situação é estado, processo ou evento considerado como unidade de interpretação.', 'Fornece base para tempo, aspecto e predicação.', ('sentido', 'contexto'), '', 'semantica_pragmatica', ('uma porta estar aberta',), ('Não é necessariamente acontecimento dinâmico.',)),
    ConceitoPortugues(533, 'relação temporal', 'Relação temporal posiciona duas situações por anterioridade, simultaneidade ou posterioridade.', 'Liga tempos verbais, narrativa e inferência.', ('situação', 'tempo verbal', 'ordem'), 'O texto pode deixar a relação indeterminada.', 'semantica_pragmatica', ('A ocorreu antes de B.',), ('Não é causa.',)),
    ConceitoPortugues(534, 'quantidade', 'Quantidade é propriedade que permite contar, medir ou comparar extensão num domínio.', 'Apoia numerais e quantificação linguística.', ('diferença', 'relação'), '', 'semantica_pragmatica', ('três livros; muita água',), ('Não é apenas número exato.',)),
    ConceitoPortugues(535, 'domínio contextual', 'Domínio contextual é o conjunto de entidades ou situações relevantes para interpretar uma expressão num contexto.', 'Limita quantificadores e referências sem universalizar.', ('contexto', 'referência', 'texto'), 'O domínio pode permanecer implícito.', 'semantica_pragmatica', ('todos os alunos desta turma',), ('Não é o universo inteiro.',)),
    ConceitoPortugues(536, 'estrutura semântica', 'Estrutura semântica é a organização de predicados, argumentos, operadores e relações de sentido.', 'Permite representar composição e escopo.', ('sentido', 'relação', 'inferência'), 'A notação formal é opcional; a relação construída é o fundamento.', 'semantica_pragmatica', ('negação aplicada a uma afirmação',), ('Não é árvore sintática por necessidade.',)),
    ConceitoPortugues(537, 'explicação', 'Explicação é texto ou relação que torna uma afirmação compreensível por causas, razões, partes ou funcionamento.', 'Apoia elaboração, ensino e argumentação.', ('exposição', 'relação', 'coerência'), 'Uma explicação pode ser clara e ainda falsa; precisa de evidência.', 'texto_discurso', ('mostrar como e por quê',), ('Não é apenas repetir a afirmação.',)),
    ConceitoPortugues(538, 'exemplificação', 'Exemplificação é relação em que um caso concreto materializa uma classe, regra ou ideia.', 'Liga conceito abstrato a ocorrência observável.', ('exemplo de uso', 'relação'), 'Um exemplo não prova universalidade.', 'texto_discurso', ('“casa” como exemplo de nome',), ('Não é definição completa.',)),
    ConceitoPortugues(539, 'causa', 'Causa é uma situação tratada como produtora ou condição explicativa de outra.', 'Sustenta relações causais e argumentos.', ('situação', 'relação'), 'Causalidade no mundo exige evidência além da sequência textual.', 'semantica_pragmatica', ('chuva causando piso molhado em contexto controlado',), ('Não é simples anterioridade.',)),
    ConceitoPortugues(540, 'hipótese', 'Hipótese é afirmação provisória proposta para teste.', 'Permite investigar sem fingir conclusão.', ('afirmação', 'inferência', 'evidência'), '', 'metalinguagem', ('tal forma pode depender deste contexto',), ('Não é fato aprovado.',)),
    ConceitoPortugues(541, 'voz discursiva', 'Voz discursiva é a fonte textual ou enunciativa a que uma fala, avaliação ou posição é atribuída.', 'Distingue narrador, autor citado e personagem.', ('texto', 'citação', 'referência'), 'A fonte pode ser implícita ou ambígua.', 'texto_discurso', ('voz do narrador e voz da personagem',), ('Não é voz verbal.',)),
    ConceitoPortugues(542, 'progressão', 'Progressão é mudança ordenada pela qual texto, argumento ou narrativa avança.', 'Generaliza progressão temática e sequencial.', ('ordem', 'coerência'), '', 'texto_discurso', ('problema → análise → conclusão',), ('Não exige crescimento linear.',)),
    ConceitoPortugues(543, 'comunidade de fala', 'Comunidade de fala é grupo cujos participantes partilham ou negociam padrões de uso e interpretação.', 'Apoia descrição de variedades sem homogeneizar pessoas.', ('uso', 'variação linguística', 'contexto'), 'As fronteiras são sociais e podem sobrepor-se.', 'variacao_letramento', ('falantes ligados por práticas comuns',), ('Não significa fala idêntica.',)),
    ConceitoPortugues(544, 'repertório linguístico', 'Repertório linguístico é o conjunto de línguas, variedades, registros e recursos disponíveis a uma pessoa ou comunidade.', 'Apoia bilinguismo, alternância e aquisição.', ('competência comunicativa', 'variação linguística'), 'Disponibilidade e domínio variam por situação.', 'variacao_letramento', ('português, outra língua e registros diversos',), ('Não é lista fixa de idiomas.',)),
    ConceitoPortugues(545, 'procedimento', 'Procedimento é sequência explícita de operações orientada a um resultado verificável.', 'Baseia descrição operacional e instrução.', ('ordem', 'instrução'), '', 'metalinguagem', ('observar → classificar → testar',), ('Não é resultado.',)),
    ConceitoPortugues(546, 'critério', 'Critério é condição explícita usada para decidir, classificar ou comparar.', 'Impede classificação intuitiva sem fundamento declarado.', ('diferença', 'relação'), '', 'metalinguagem', ('presença de verbo finito como critério',), ('Não é resultado da decisão.',)),
    ConceitoPortugues(547, 'lacuna de conhecimento', 'Lacuna de conhecimento é dependência, dado ou operação ainda não construída ou validada.', 'Torna explícito o que falta e impede antecipação.', ('reconstrução linguística PSF', 'diferença'), 'Deve ser reduzida por construção, nunca escondida.', 'metalinguagem', ('inventário regional ainda ausente',), ('Não é convite para inventar.',)),
    ConceitoPortugues(548, 'destinatário', 'Destinatário é participante a quem um enunciado ou texto é dirigido.', 'Liga intenção, gênero e escolhas de registro.', ('enunciado', 'intenção comunicativa', 'referência'), 'Pode ser múltiplo, implícito ou imaginado.', 'texto_discurso', ('leitor de uma carta',), ('Não é necessariamente receptor efetivo.',)),
    ConceitoPortugues(549, 'gênero digital', 'Gênero digital é gênero textual cuja produção, circulação ou interação depende de ambiente digital.', 'Agrupa correio eletrónico, mensagem e outros formatos sem os tornar idênticos.', ('gênero textual', 'multimodalidade'), 'Formatos mudam com plataformas e usos.', 'texto_discurso', ('email',), ('Não é tipo textual único.',)),
    ConceitoPortugues(550, 'gênero informativo', 'Gênero informativo prioriza apresentação verificável de fatos, dados ou explicações.', 'Agrupa notícia e reportagem por finalidade dominante.', ('gênero textual', 'exposição', 'evidência'), 'Pode conter interpretação e seleção editorial.', 'texto_discurso', ('notícia',), ('Informativo não garante verdade.',)),
    ConceitoPortugues(551, 'gênero formal', 'Gênero formal segue convenções institucionais explícitas para cumprir função administrativa, académica ou profissional.', 'Agrupa requerimentos, atas e relatórios por situação de uso.', ('gênero textual', 'formalidade', 'norma'), 'As convenções precisam ser verificadas por instituição.', 'texto_discurso', ('requerimento',), ('Formal não significa melhor em todo contexto.',)),
    ConceitoPortugues(552, 'gênero literário', 'Gênero literário organiza produção verbal estética por convenções abertas de narrativa, poesia ou drama.', 'Permite relacionar obras sem impor fronteiras absolutas.', ('gênero textual', 'estilo', 'conotação'), 'Obras podem misturar gêneros.', 'texto_discurso', ('conto; poema; romance',), ('Não é garantia de ficção.',)),
    ConceitoPortugues(553, 'gênero dramático', 'Gênero dramático organiza ações e falas para representação ou leitura cénica.', 'Sustenta peça teatral e diálogo dramático.', ('gênero literário', 'diálogo', 'multimodalidade'), '', 'texto_discurso', ('peça teatral',), ('Não é toda conversa com conflito.',)),
    ConceitoPortugues(554, 'pesquisa', 'Pesquisa é procedimento sistemático de formular problema, recolher evidência, comparar e registrar conclusão provisória.', 'Apoia reportagem, monografia e reconstrução PSF.', ('hipótese', 'procedimento', 'evidência'), 'Resultados dependem da qualidade dos dados e métodos.', 'metalinguagem', ('pergunta → dados → teste → conclusão',), ('Não é busca sem critério.',)),
    ConceitoPortugues(555, 'turno de fala', 'Turno de fala é intervalo em que um participante detém a palavra numa interação.', 'Permite analisar alternância em diálogo e entrevista.', ('diálogo', 'fala', 'ordem'), 'Sobreposição e interrupção exigem marcação própria.', 'texto_discurso', ('pergunta num turno, resposta no seguinte',), ('Não é parágrafo.',)),
    ConceitoPortugues(556, 'figura de linguagem', 'Figura de linguagem é construção que produz efeito por relação não literal, repetição, contraste ou desvio funcional.', 'Generaliza metáfora, metonímia, ironia e outras figuras.', ('conotação', 'estilo', 'relação'), 'A identificação depende de contexto e efeito.', 'semantica_pragmatica', ('metáfora',), ('Não é erro gramatical.',)),
    ConceitoPortugues(557, 'fonotática', 'Fonotática é o conhecimento das combinações de fonemas admitidas numa posição de sílaba ou palavra.', 'Permite distinguir sequência possível, rara e ainda não validada.', ('fonema', 'sílaba', 'combinação'), 'O inventário concreto precisa ser construído separadamente por variedade.', 'fonetica_fonologia', ('prato começa por grupo consonantal possível',), ('Não é ortografia: trata organização sonora.',)),
    ConceitoPortugues(558, 'sequência fonotática', 'Sequência fonotática é uma cadeia ordenada de unidades sonoras examinada quanto à sua posição e combinabilidade.', 'Materializa o objeto que a fonotática testa.', ('fonotática', 'sequência de fonemas'), 'A aceitabilidade pode variar por palavra, empréstimo e variedade.', 'fonetica_fonologia', ('/pr/ no início de prato',), ('Não é qualquer sequência de letras.',)),
    ConceitoPortugues(559, 'margem silábica', 'Margem silábica é a parte periférica da sílaba formada pelo ataque e, quando existe, pela coda.', 'Separa periferia consonantal de núcleo silábico.', ('ataque silábico', 'coda silábica', 'núcleo silábico'), '', 'fonetica_fonologia', ('pr- em pra; -r em mar',), ('O núcleo não pertence à margem.',)),
    ConceitoPortugues(560, 'rima silábica', 'Rima silábica é a unidade formada pelo núcleo da sílaba e pela coda que o segue, quando existe.', 'Permite comparar sílabas pelo seu final sonoro.', ('núcleo silábico', 'coda silábica', 'sílaba'), '', 'fonetica_fonologia', ('-ar em mar',), ('Não é rima poética completa.',)),
    ConceitoPortugues(561, 'sílaba aberta', 'Sílaba aberta termina no núcleo, sem coda consonantal no recorte adotado.', 'Distingue estruturas silábicas terminadas em vogal.', ('sílaba', 'núcleo silábico', 'coda silábica'), 'A análise pode mudar conforme a realização fonética da variedade.', 'fonetica_fonologia', ('má em mapa',), ('Aberta não significa necessariamente vogal aberta.',)),
    ConceitoPortugues(562, 'sílaba fechada', 'Sílaba fechada possui coda depois do núcleo no recorte adotado.', 'Distingue estruturas silábicas com fechamento periférico.', ('sílaba', 'núcleo silábico', 'coda silábica'), 'A identificação concreta depende da pronúncia analisada.', 'fonetica_fonologia', ('mar',), ('Fechada não significa vogal fechada.',)),
    ConceitoPortugues(563, 'ataque simples', 'Ataque simples contém uma unidade consonantal antes do núcleo silábico.', 'Permite classificar a complexidade do início da sílaba.', ('ataque silábico', 'consoante'), '', 'fonetica_fonologia', ('p- em pá',), ('Não é ataque complexo.',)),
    ConceitoPortugues(564, 'ataque complexo', 'Ataque complexo contém mais de uma unidade consonantal antes do núcleo silábico.', 'Permite investigar grupos consonantais iniciais.', ('ataque silábico', 'encontro consonantal', 'fonotática'), 'As combinações aceites variam por posição e variedade.', 'fonetica_fonologia', ('pr- em prato',), ('Duas letras podem representar uma só unidade e não formar ataque complexo.',)),
    ConceitoPortugues(565, 'coda simples', 'Coda simples contém uma unidade depois do núcleo silábico.', 'Permite descrever fechamento silábico elementar.', ('coda silábica', 'consoante'), 'A realização concreta varia entre variedades.', 'fonetica_fonologia', ('-r em mar',), ('Não é ataque.',)),
    ConceitoPortugues(566, 'coda complexa', 'Coda complexa contém mais de uma unidade depois do núcleo silábico no recorte fonológico adotado.', 'Permite marcar finais silábicos de maior complexidade.', ('coda silábica', 'fonotática'), 'A existência e análise dependem da variedade e da fronteira morfológica.', 'fonetica_fonologia', ('estrutura final a validar por variedade',), ('Não deve ser inferida apenas pela escrita.',)),
    ConceitoPortugues(567, 'palavra fonológica', 'Palavra fonológica é unidade organizada por acento e continuidade sonora, que pode não coincidir perfeitamente com a palavra gráfica.', 'Liga tonicidade, clíticos e ritmo.', ('palavra', 'prosódia', 'tonicidade'), 'A delimitação operacional ainda precisa de regras por variedade.', 'fonetica_fonologia', ('um clítico pode apoiar-se na palavra vizinha',), ('Não é sinónimo obrigatório de palavra escrita.',)),
    ConceitoPortugues(568, 'grupo prosódico', 'Grupo prosódico é conjunto de unidades pronunciadas sob uma organização comum de ritmo, acento e entoação.', 'Permite analisar fala acima da palavra isolada.', ('palavra fonológica', 'ritmo', 'entoação'), 'Os limites concretos exigem fala observada.', 'fonetica_fonologia', ('uma frase curta dita num só contorno',), ('Não é necessariamente uma oração.',)),
    ConceitoPortugues(569, 'acento lexical', 'Acento lexical é a proeminência relativa associada a uma palavra no sistema.', 'Distingue posição tônica da palavra antes do enunciado completo.', ('tonicidade', 'palavra fonológica'), 'Há palavras e variedades com comportamento que exige análise própria.', 'fonetica_fonologia', ('café tem proeminência final',), ('Não é acento gráfico.',)),
    ConceitoPortugues(570, 'acento frásico', 'Acento frásico é a proeminência que uma unidade recebe dentro do enunciado.', 'Permite destacar informação na fala.', ('acento lexical', 'enunciado', 'prosódia'), 'A posição depende de foco, ritmo e contexto.', 'fonetica_fonologia', ('EU fiz, com destaque em eu',), ('Não altera necessariamente a grafia.',)),
    ConceitoPortugues(571, 'foco prosódico', 'Foco prosódico é destaque sonoro usado para selecionar ou contrastar uma parte do enunciado.', 'Liga intenção comunicativa e realização sonora.', ('acento frásico', 'intenção comunicativa', 'foco informacional'), 'A interpretação exige contexto e não deve ser adivinhada.', 'fonetica_fonologia', ('Eu disse HOJE, não amanhã.',), ('Nem toda intensidade é foco.',)),
    ConceitoPortugues(572, 'contorno entoacional', 'Contorno entoacional é o percurso relativo da altura da voz ao longo de um grupo prosódico.', 'Ajuda a distinguir continuidade, pergunta, afirmação e atitude sem reduzir tudo à pontuação.', ('entoação', 'grupo prosódico'), 'A forma concreta varia por falante e variedade.', 'fonetica_fonologia', ('subida final possível em pergunta',), ('Não é regra absoluta de interrogação.',)),
    ConceitoPortugues(573, 'fronteira prosódica', 'Fronteira prosódica é um limite percebido por pausa, alongamento, mudança de ritmo ou contorno.', 'Permite segmentar fala contínua.', ('pausa', 'grupo prosódico', 'contorno entoacional'), 'A deteção automática ainda não está implementada.', 'fonetica_fonologia', ('pausa entre dois grupos',), ('Não coincide sempre com vírgula.',)),
    ConceitoPortugues(574, 'assimilação regressiva', 'Assimilação regressiva ocorre quando uma unidade posterior influencia uma anterior.', 'Distingue a direção de um processo de aproximação sonora.', ('assimilação fonológica', 'sequência fonotática'), 'Os casos concretos precisam ser observados por variedade.', 'fonetica_fonologia', ('influência do som seguinte',), ('Não é regra ortográfica automática.',)),
    ConceitoPortugues(575, 'assimilação progressiva', 'Assimilação progressiva ocorre quando uma unidade anterior influencia uma posterior.', 'Completa a distinção direcional da assimilação.', ('assimilação fonológica', 'sequência fonotática'), 'Os casos concretos precisam ser observados por variedade.', 'fonetica_fonologia', ('influência do som anterior',), ('Não é simples repetição.',)),
    ConceitoPortugues(576, 'dissimilação', 'Dissimilação é mudança que aumenta a diferença entre unidades semelhantes numa sequência.', 'Permite descrever afastamento articulatório ou fonológico.', ('oposição fonológica', 'sequência fonotática'), 'A produtividade no português atual deve ser validada por dados.', 'fonetica_fonologia', ('forma histórica a ser reconstruída, não presumida',), ('Não é assimilação.',)),
    ConceitoPortugues(577, 'síncope', 'Síncope é perda de unidade sonora no interior de uma palavra ou grupo.', 'Localiza elisão interna.', ('elisão', 'palavra fonológica'), 'A ocorrência varia por ritmo, registro e variedade.', 'fonetica_fonologia', ('perda interna em fala rápida a observar',), ('Não é apócope.',)),
    ConceitoPortugues(578, 'apócope', 'Apócope é perda de unidade sonora no final de uma palavra.', 'Localiza elisão final.', ('elisão', 'palavra fonológica'), 'Os casos produtivos precisam ser descritos por variedade.', 'fonetica_fonologia', ('redução final a observar',), ('Não é síncope.',)),
    ConceitoPortugues(579, 'prótese', 'Prótese é acréscimo de unidade no início de uma forma.', 'Distingue epêntese inicial.', ('epêntese', 'palavra fonológica'), 'O inventário histórico e regional permanece aberto.', 'fonetica_fonologia', ('acréscimo inicial a validar',), ('Não é prefixação morfológica.',)),
    ConceitoPortugues(580, 'paragoge', 'Paragoge é acréscimo de unidade no final de uma forma.', 'Distingue epêntese final.', ('epêntese', 'palavra fonológica'), 'O inventário histórico e regional permanece aberto.', 'fonetica_fonologia', ('acréscimo final a validar',), ('Não é sufixação morfológica.',)),
    ConceitoPortugues(581, 'segmentação gráfica', 'Segmentação gráfica é a divisão da escrita em palavras, sinais e blocos visíveis.', 'Permite reconstruir limites escritos sem confundi-los com limites sonoros.', ('grafema', 'espaço', 'pontuação'), 'Casos de hífen, contração e expressão fixa exigem regras próprias.', 'ortografia', ('a casa',), ('Não é separação silábica.',)),
    ConceitoPortugues(582, 'juntura vocabular', 'Juntura vocabular é a fronteira entre palavras ou formas na cadeia escrita e falada.', 'Ajuda a investigar união indevida e separação indevida.', ('segmentação gráfica', 'palavra', 'fronteira prosódica'), 'A fala pode ocultar fronteiras que a escrita conserva.', 'ortografia', ('de repente, não derepente',), ('Não é apenas espaço físico.',)),
    ConceitoPortugues(583, 'grafia lexical', 'Grafia lexical é a forma escrita estabilizada de uma unidade lexical.', 'Permite comparar pronúncia, família e convenção escrita.', ('forma lexical', 'ortografia'), 'A grafia de cada item precisa ser materializada e testada, não adivinhada.', 'ortografia', ('casa',), ('Não é transcrição fonética.',)),
    ConceitoPortugues(584, 'convenção ortográfica', 'Convenção ortográfica é regularidade coletiva que estabiliza uma escolha gráfica.', 'Explica por que escrita não é cópia exata de som.', ('norma', 'ortografia', 'uso'), 'Mudanças históricas e diferenças oficiais exigem fonte de comparação e reconstrução.', 'ortografia', ('uso partilhado de letras e sinais',), ('Não é verdade natural imutável.',)),
    ConceitoPortugues(585, 'variante gráfica', 'Variante gráfica é forma escrita alternativa ligada à mesma unidade em contexto, época ou norma identificada.', 'Permite registrar diferença sem declarar erro automaticamente.', ('grafia lexical', 'variação linguística', 'norma'), 'Cada variante precisa de contexto explícito.', 'ortografia', ('forma A / forma B quando ambas forem validadas',), ('Não é erro por definição.',)),
    ConceitoPortugues(586, 'homofonia', 'Homofonia é relação entre formas de som igual ou muito próximo e grafia ou sentido diferente.', 'Explica por que ouvir pode não bastar para escolher grafia.', ('som', 'grafia lexical', 'sentido'), 'A igualdade sonora depende da variedade.', 'ortografia', ('cem e sem em variedades onde coincidem',), ('Não é homografia.',)),
    ConceitoPortugues(587, 'homografia', 'Homografia é relação entre formas escritas iguais que podem ter leitura, classe ou sentido diferente.', 'Explica ambiguidade preservada pela escrita.', ('grafia lexical', 'polissemia', 'homonímia'), 'A classificação entre polissemia e homonímia pode exigir história lexical.', 'ortografia', ('forma escrita igual com sentidos distintos',), ('Não garante pronúncia igual.',)),
    ConceitoPortugues(588, 'uso de h', 'O uso de h é uma escolha gráfica que em muitas posições não corresponde a som próprio, mas distingue grafias e famílias.', 'Impede deduzir h apenas pela audição.', ('letra', 'grafia lexical', 'família ortográfica'), 'O inventário lexical e os casos de dígrafo precisam ser testados por família.', 'ortografia', ('homem; hoje; nh; ch; lh',), ('H isolado e h em dígrafo têm funções diferentes.',)),
    ConceitoPortugues(589, 'uso de r', 'O uso de r registra valores e posições diferentes conforme início, interior, final e vizinhança gráfica.', 'Prepara a distinção entre r e rr.', ('letra', 'grafia lexical', 'correspondência som-grafema'), 'A realização sonora varia entre variedades.', 'ortografia', ('rato; caro; mar',), ('Um r gráfico não tem sempre o mesmo som.',)),
    ConceitoPortugues(590, 'uso de rr', 'O uso de rr ocorre no interior de palavra entre vogais para conservar um valor consonantal forte na convenção escrita.', 'Distingue pares gráficos como caro e carro.', ('uso de r', 'dígrafo', 'vogal'), 'Famílias derivadas e fronteiras morfológicas devem ser testadas.', 'ortografia', ('carro',), ('RR não aparece normalmente no início da palavra.',)),
    ConceitoPortugues(591, 'uso de m antes de p e b', 'Na grafia portuguesa, m é usado frequentemente para marcar nasalidade antes de p e b.', 'Constrói uma família ortográfica observável.', ('nasalidade', 'grafia lexical', 'consoante'), 'Empréstimos, nomes próprios e fronteiras morfológicas precisam ser verificados.', 'ortografia', ('campo; também',), ('Não autoriza trocar todo n por m.',)),
    ConceitoPortugues(592, 'uso de n antes de consoante', 'N pode marcar nasalidade antes de diversas consoantes fora da família p/b.', 'Complementa a distinção gráfica m/n em posição interna.', ('nasalidade', 'grafia lexical', 'uso de m antes de p e b'), 'A escolha concreta continua lexical e precisa de famílias testadas.', 'ortografia', ('canto',), ('Não é regra suficiente para todas as palavras.',)),
    ConceitoPortugues(593, 'uso de e e i átonos', 'E e i em posição átona podem aproximar-se na fala de certas variedades sem se tornarem grafias livremente intercambiáveis.', 'Separa redução fonética de decisão ortográfica.', ('vogal átona', 'grafia lexical', 'variação regional'), 'A correspondência precisa ser construída por famílias lexicais e variedade.', 'ortografia', ('grafia deve ser confirmada pela família, não apenas pelo som',), ('Não é licença para escrever pela pronúncia local.',)),
    ConceitoPortugues(594, 'uso de o e u átonos', 'O e u em posição átona podem aproximar-se na fala de certas variedades, mantendo distinções gráficas lexicais.', 'Separa realização sonora e convenção escrita.', ('vogal átona', 'grafia lexical', 'variação regional'), 'A correspondência precisa ser construída por famílias lexicais e variedade.', 'ortografia', ('grafia lexical deve ser validada',), ('Não é regra universal de pronúncia.',)),
    ConceitoPortugues(595, 'maiúscula no início de frase', 'Maiúscula no início de frase é marca gráfica convencional colocada na primeira unidade alfabética relevante após limite final.', 'Ajuda a reconhecer começo de unidade escrita.', ('maiúscula inicial', 'frase', 'ponto final'), 'Casos após dois-pontos, enumeração e citação exigem contexto.', 'ortografia', ('A criança lê.',), ('Não transforma a palavra em nome próprio.',)),
    ConceitoPortugues(596, 'maiúscula em nome próprio', 'Maiúscula em nome próprio marca convencionalmente uma referência individualizada na escrita.', 'Relaciona categoria nominal e apresentação gráfica.', ('substantivo próprio', 'maiúscula'), 'Títulos, instituições e usos estilísticos precisam de regras específicas.', 'ortografia', ('Maputo',), ('Maiúscula não prova que todo uso seja nome próprio.',)),
    ConceitoPortugues(597, 'ponto em abreviatura', 'Ponto em abreviatura pode marcar supressão gráfica de parte de uma palavra.', 'Distingue abreviatura de palavra integral e de algumas siglas.', ('abreviatura', 'ponto final'), 'Há abreviaturas sem o mesmo padrão e convenções especializadas.', 'ortografia', ('p. como forma abreviada validada em contexto',), ('Não é ponto final de frase por necessidade.',)),
    ConceitoPortugues(598, 'símbolo não alfabético', 'Símbolo não alfabético é marca convencional que representa medida, operação, moeda ou outra unidade sem funcionar como letra.', 'Amplia o inventário gráfico sem confundir símbolo e palavra.', ('grafema', 'marca', 'convenção ortográfica'), 'Cada sistema de símbolos precisa de domínio e regra próprios.', 'ortografia', ('%',), ('Não é sigla nem abreviatura comum.',)),
    ConceitoPortugues(599, 'vírgula de enumeração', 'Vírgula de enumeração separa unidades coordenadas numa série quando não há conectivo entre todas elas.', 'Materializa uma função básica da vírgula.', ('vírgula', 'enumeração', 'coordenação'), '', 'pontuacao', ('Trouxe pão, água, fruta e chá.',), ('Não separa automaticamente sujeito e verbo.',)),
    ConceitoPortugues(600, 'vírgula de vocativo', 'Vírgula de vocativo isola a unidade usada para chamar ou dirigir-se ao interlocutor.', 'Liga pontuação e função sintática do vocativo.', ('vírgula', 'vocativo', 'enunciado'), '', 'pontuacao', ('Maria, venha aqui.',), ('O vocativo não é sujeito por necessidade.',)),
    ConceitoPortugues(601, 'vírgula de aposto', 'Vírgula de aposto pode isolar aposto explicativo acrescentado a uma referência.', 'Liga pontuação e explicação nominal.', ('vírgula', 'aposto', 'retomada'), 'Aposto restritivo e estruturas sem pausa exigem distinção.', 'pontuacao', ('Maputo, capital de Moçambique, fica no sul.',), ('Nem todo aposto recebe vírgulas.',)),
    ConceitoPortugues(602, 'dois-pontos de citação', 'Dois-pontos de citação podem anunciar fala ou trecho citado.', 'Liga pontuação e introdução do discurso de outra voz.', ('dois-pontos', 'citação', 'discurso direto'), '', 'pontuacao', ('Ela disse: “Voltarei.”',), ('A citação pode ser integrada por outras construções.',)),
