    ConceitoPortugues(665, 'estado', 'Estado é situação apresentada sem mudança interna necessária no intervalo considerado.', 'Contrasta leituras estáticas e dinâmicas.', ('situação', 'aspecto verbal'), '', 'semantica_pragmatica', ('saber uma resposta',), ('Estado pode mudar fora do intervalo.',)),
    ConceitoPortugues(666, 'processo', 'Processo é situação dinâmica apresentada em desenvolvimento, sem ponto final obrigatório na leitura.', 'Distingue desenvolvimento de estado e resultado.', ('evento', 'aspecto verbal'), '', 'semantica_pragmatica', ('caminhar',), ('Pode receber limite por contexto.',)),
    ConceitoPortugues(667, 'mudança de estado', 'Mudança de estado é transição de uma condição para outra.', 'Liga evento, resultado e aspecto.', ('evento', 'estado', 'relação temporal'), '', 'semantica_pragmatica', ('a porta abriu',), ('Não é todo processo.',)),
    ConceitoPortugues(668, 'telicidade', 'Telicidade é a presença de um ponto final interno que completa a situação na leitura considerada.', 'Distingue eventos orientados a resultado de atividades abertas.', ('evento', 'mudança de estado', 'aspecto verbal'), 'A leitura depende de objeto, quantidade e contexto.', 'semantica_pragmatica', ('ler o livro inteiro',), ('Tempo passado não garante telicidade.',)),
    ConceitoPortugues(669, 'quantificação', 'Quantificação constrói quantidade, extensão ou distribuição de uma referência.', 'Liga numerais, determinantes e escopo.', ('quantidade', 'referência', 'determinante'), 'Quantidades vagas e coletivas exigem análise própria.', 'semantica_pragmatica', ('todos os livros; três livros',), ('Não é apenas numeral explícito.',)),
    ConceitoPortugues(670, 'quantificador universal', 'Quantificador universal apresenta a relação como aplicável a todos os membros do domínio contextual.', 'Materializa leitura de totalidade.', ('quantificação', 'domínio contextual'), 'O domínio precisa ser identificado; não é o universo inteiro por padrão.', 'semantica_pragmatica', ('todas as crianças da turma',), ('Não prova existência do domínio.',)),
    ConceitoPortugues(671, 'quantificador existencial', 'Quantificador existencial apresenta pelo menos um membro do domínio contextual como participante.', 'Materializa leitura de existência localizada.', ('quantificação', 'existência', 'domínio contextual'), '', 'semantica_pragmatica', ('alguma criança chegou',), ('Não identifica qual membro sem contexto.',)),
    ConceitoPortugues(672, 'escopo', 'Escopo é a parte da estrutura interpretativa sobre a qual um operador ou expressão exerce efeito.', 'Explica ambiguidades de negação, quantificação e modalidade.', ('relação', 'estrutura semântica'), 'O escopo pode ser ambíguo e precisa de estrutura/contexto.', 'semantica_pragmatica', ('não + todos pode ter mais de uma leitura',), ('Não é posição linear apenas.',)),
    ConceitoPortugues(673, 'escopo da negação', 'Escopo da negação é a unidade cujo conteúdo é negado numa leitura.', 'Distingue negação total, parcial e contrastiva.', ('negação', 'escopo'), 'Prosódia e contexto podem alterar a leitura.', 'semantica_pragmatica', ('Não comprei TODOS os livros.',), ('A palavra não não nega sempre a frase inteira.',)),
    ConceitoPortugues(674, 'dêixis pessoal', 'Dêixis pessoal localiza participantes a partir de quem fala, ouve ou é referido.', 'Aprofunda pessoa gramatical e pronomes.', ('dêixis', 'pessoa gramatical', 'enunciado'), '', 'semantica_pragmatica', ('eu, tu, nós em contexto',), ('A referência muda com o falante.',)),
    ConceitoPortugues(675, 'dêixis espacial', 'Dêixis espacial localiza entidades em relação ao ponto de referência discursivo.', 'Liga demonstrativos, advérbios e contexto.', ('dêixis', 'localização semântica', 'contexto'), '', 'semantica_pragmatica', ('aqui; ali',), ('Distâncias variam por sistema de uso.',)),
    ConceitoPortugues(676, 'dêixis temporal', 'Dêixis temporal localiza situações em relação ao momento ou ponto temporal do enunciado.', 'Liga advérbios e tempos verbais.', ('dêixis', 'tempo verbal', 'contexto'), '', 'semantica_pragmatica', ('hoje; amanhã',), ('O referente muda conforme a data do enunciado.',)),
    ConceitoPortugues(677, 'dêixis discursiva', 'Dêixis discursiva aponta para partes do próprio texto ou discurso.', 'Ajuda a organizar referência metatextual.', ('dêixis', 'texto', 'retomada'), '', 'semantica_pragmatica', ('como veremos adiante',), ('Não aponta necessariamente para objeto externo.',)),
    ConceitoPortugues(678, 'cortesia linguística', 'Cortesia linguística é gestão verbal de distância, respeito, aproximação e impacto social numa interação.', 'Explica escolhas de tratamento, pedido e mitigação.', ('pragmática', 'registro', 'ato de fala'), 'Normas de cortesia variam culturalmente e não devem ser universalizadas.', 'semantica_pragmatica', ('Poderia ajudar-me?',), ('Cortesia formal não garante intenção benevolente.',)),
    ConceitoPortugues(679, 'macroestrutura textual', 'Macroestrutura textual é a organização global dos conteúdos principais de um texto.', 'Permite resumir e verificar progressão além de frases isoladas.', ('texto', 'tema', 'progressão temática'), 'A extração automática ainda é parcial.', 'texto_discurso', ('tema central e partes principais',), ('Não é apenas título.',)),
    ConceitoPortugues(680, 'microestrutura textual', 'Microestrutura textual é a rede local de palavras, frases, conectivos e retomadas que sustenta o texto.', 'Liga coesão local à macroestrutura.', ('texto', 'coesão', 'frase'), '', 'texto_discurso', ('relações entre frases vizinhas',), ('Não substitui coerência global.',)),
    ConceitoPortugues(681, 'organização retórica', 'Organização retórica é a disposição funcional de partes para informar, narrar, argumentar ou orientar.', 'Relaciona intenção, gênero e estrutura textual.', ('intenção comunicativa', 'gênero textual', 'tipo textual'), 'Pode haver mais de uma organização no mesmo texto.', 'texto_discurso', ('problema → análise → solução',), ('Não é decoração estilística apenas.',)),
    ConceitoPortugues(682, 'relação de elaboração', 'Relação de elaboração ocorre quando um trecho desenvolve, exemplifica ou especifica outro.', 'Materializa uma conexão de coerência.', ('coerência', 'explicação', 'exemplificação'), '', 'texto_discurso', ('A planta cresceu. Novas folhas apareceram.',), ('Não é repetição idêntica.',)),
    ConceitoPortugues(683, 'relação de causa', 'Relação de causa liga uma situação tratada como razão para outra.', 'Permite analisar conectivos e inferências causais.', ('coerência', 'causa'), 'Texto pode alegar causa sem prová-la no mundo.', 'texto_discurso', ('Choveu, por isso a rua molhou.',), ('Sequência temporal não prova causa.',)),
    ConceitoPortugues(684, 'relação de contraste', 'Relação de contraste aproxima conteúdos por diferença, oposição ou quebra de expectativa.', 'Liga adversidade, concessão e antítese.', ('coerência', 'oposição'), '', 'texto_discurso', ('Estudou, mas não passou.',), ('Contraste não é contradição lógica automática.',)),
    ConceitoPortugues(685, 'relação de condição', 'Relação de condição apresenta uma situação como requisito, hipótese ou enquadramento de outra.', 'Liga orações condicionais e raciocínio hipotético.', ('coerência', 'hipótese'), '', 'texto_discurso', ('Se houver tempo, iremos.',), ('Condição não afirma ocorrência.',)),
    ConceitoPortugues(686, 'relação de sequência', 'Relação de sequência ordena ações, estados ou partes no tempo ou na exposição.', 'Sustenta instrução, narração e progressão.', ('coerência', 'ordem'), '', 'texto_discurso', ('primeiro, depois, por fim',), ('Ordem textual e ordem real podem divergir.',)),
    ConceitoPortugues(687, 'estrutura narrativa', 'Estrutura narrativa organiza participantes, acontecimentos, tempo, espaço, conflito e desfecho.', 'Aprofunda a narração como construção textual.', ('narração', 'organização retórica'), 'Narrativas podem quebrar ou omitir partes do padrão.', 'texto_discurso', ('situação inicial → mudança → desfecho',), ('Não é fórmula obrigatória.',)),
    ConceitoPortugues(688, 'narrador', 'Narrador é a voz textual que apresenta a narrativa.', 'Distingue voz narrativa de autor real.', ('estrutura narrativa', 'voz discursiva'), 'A identificação pode ser ambígua.', 'texto_discurso', ('narrador em primeira pessoa',), ('Narrador não é automaticamente o autor.',)),
    ConceitoPortugues(689, 'personagem', 'Personagem é participante construído no universo narrativo.', 'Permite acompanhar ações, estados e relações na narrativa.', ('estrutura narrativa', 'referente'), '', 'texto_discurso', ('a protagonista do conto',), ('Não precisa corresponder a pessoa real.',)),
    ConceitoPortugues(690, 'enredo', 'Enredo é a organização dos acontecimentos narrados e de suas relações.', 'Liga sequência, conflito e transformação.', ('estrutura narrativa', 'evento', 'relação de sequência'), '', 'texto_discurso', ('acontecimentos organizados numa história',), ('Não é simples lista cronológica.',)),
    ConceitoPortugues(691, 'espaço narrativo', 'Espaço narrativo é o lugar construído ou referido em que eventos da narrativa são situados.', 'Liga descrição, dêixis e ação narrativa.', ('estrutura narrativa', 'localização semântica'), '', 'texto_discurso', ('a aldeia onde ocorre a história',), ('Não é necessariamente lugar real.',)),
    ConceitoPortugues(692, 'tempo narrativo', 'Tempo narrativo é a organização temporal dos eventos e da sua apresentação no texto.', 'Distingue ordem dos fatos, duração e momento da narração.', ('estrutura narrativa', 'tempo verbal', 'relação temporal'), 'Retrocesso e antecipação exigem conceitos adicionais.', 'texto_discurso', ('o texto começa pelo fim e retorna ao início',), ('Não é apenas tempo verbal.',)),
    ConceitoPortugues(693, 'conflito narrativo', 'Conflito narrativo é tensão entre objetivos, forças, valores ou situações que impulsiona transformação no enredo.', 'Ajuda a explicar progressão de muitas narrativas.', ('enredo', 'oposição'), 'Nem toda narrativa depende de conflito forte.', 'texto_discurso', ('personagem quer partir, mas algo impede',), ('Não é discussão verbal por necessidade.',)),
    ConceitoPortugues(694, 'clímax', 'Clímax é ponto de máxima tensão ou viragem relevante numa organização narrativa.', 'Localiza concentração estrutural do conflito.', ('conflito narrativo', 'progressão'), 'Algumas narrativas distribuem ou evitam um único clímax.', 'texto_discurso', ('momento decisivo da história',), ('Não é sempre o final.',)),
    ConceitoPortugues(695, 'desfecho', 'Desfecho é a parte que apresenta resultado, fechamento ou nova estabilidade após a progressão narrativa.', 'Relaciona conflito e conclusão.', ('enredo', 'clímax', 'conclusão textual'), 'Pode ser aberto, suspenso ou múltiplo.', 'texto_discurso', ('resultado final da narrativa',), ('Não exige solução completa.',)),
    ConceitoPortugues(696, 'variedade nacional', 'Variedade nacional é conjunto de padrões associados ao uso do português num país ou comunidade nacional, sem apagar diversidade interna.', 'Permite identificar contexto amplo sem declarar uma única norma total.', ('variação regional', 'comunidade de fala', 'norma'), 'Cada variedade precisa de dados próprios e não pode ser inventada por comparação superficial.', 'variacao_letramento', ('português usado em Moçambique, descrito por evidência própria',), ('Não significa que todos os falantes usem a mesma forma.',)),
    ConceitoPortugues(697, 'língua primeira', 'Língua primeira é a língua ou conjunto de línguas adquirido inicialmente na vida de uma pessoa.', 'Apoia análise de aquisição e repertório linguístico.', ('aquisição da linguagem', 'repertório linguístico'), 'Pode haver aquisição inicial de mais de uma língua.', 'variacao_letramento', ('duas línguas adquiridas desde cedo',), ('Não determina proficiência futura.',)),
    ConceitoPortugues(698, 'língua segunda', 'Língua segunda é língua adquirida depois ou além da primeira, em contexto social ou educativo.', 'Distingue trajetória de aquisição sem hierarquizar valor.', ('aquisição da linguagem', 'língua primeira', 'bilinguismo'), 'A fronteira com língua estrangeira depende do contexto de uso.', 'variacao_letramento', ('português aprendido após outra língua inicial',), ('Não significa língua inferior.',)),
    ConceitoPortugues(699, 'texto-fonte', 'Texto-fonte é o texto tomado como ponto de partida numa operação de tradução.', 'Define a origem material da reconstrução tradutória.', ('tradução', 'texto'), '', 'texto_discurso', ('texto antes da tradução',), ('Não é fonte de verdade automática.',)),
    ConceitoPortugues(700, 'texto-alvo', 'Texto-alvo é o texto produzido na língua de chegada por uma operação de tradução.', 'Define o produto que será comparado ao texto-fonte e ao objetivo.', ('tradução', 'texto-fonte'), '', 'texto_discurso', ('texto depois da tradução',), ('Não deve copiar estrutura de origem cegamente.',)),
    ConceitoPortugues(701, 'unidade de tradução', 'Unidade de tradução é o trecho mínimo escolhido para resolver uma decisão tradutória sem perder relações necessárias.', 'Impede traduzir sempre palavra por palavra.', ('texto-fonte', 'texto-alvo', 'sentido'), 'A unidade pode ser palavra, expressão, frase ou trecho conforme o problema.', 'texto_discurso', ('uma expressão fixa tratada como conjunto',), ('Não é tamanho fixo universal.',)),
    ConceitoPortugues(702, 'tradução literal', 'Tradução literal preserva de perto forma e ordem do texto-fonte quando isso continua funcional e fiel no texto-alvo.', 'Serve como hipótese inicial controlada, não como regra absoluta.', ('unidade de tradução', 'equivalência tradutória'), 'Pode falhar em idiomatismos, sintaxe e contexto.', 'texto_discurso', ('tradução próxima quando as estruturas correspondem',), ('Literal não significa automaticamente correta.',)),
    ConceitoPortugues(703, 'tradução funcional', 'Tradução funcional prioriza a função e o efeito comunicativo relevante no texto-alvo, preservando o conteúdo justificável.', 'Permite afastar-se da forma quando necessário e explicado.', ('unidade de tradução', 'intenção comunicativa', 'adequação linguística'), 'Exige justificar perdas, ganhos e escolhas.', 'texto_discurso', ('adaptar uma instrução para funcionar na língua-alvo',), ('Não é liberdade para inventar conteúdo.',)),
    ConceitoPortugues(704, 'interferência linguística', 'Interferência linguística é influência de uma língua ou variedade sobre o uso de outra no repertório do falante.', 'Ajuda a investigar transferências sem tratar diferença como incapacidade.', ('contacto linguístico', 'língua primeira', 'língua segunda'), 'A causa precisa ser observada, não presumida por um erro isolado.', 'variacao_letramento', ('ordem transferida de outra língua, quando comprovada',), ('Não é sempre erro.',)),
    ConceitoPortugues(705, 'consciência linguística', 'Consciência linguística é capacidade de observar e refletir sobre formas, sentidos e usos da própria linguagem.', 'Liga aprendizagem, revisão e metalinguagem.', ('metalinguagem', 'análise linguística', 'revisão'), '', 'variacao_letramento', ('perceber por que duas frases diferem',), ('Não exige decorar terminologia.',)),
    ConceitoPortugues(706, 'dado linguístico', 'Dado linguístico é ocorrência, forma, julgamento ou medida registrada para análise.', 'Fornece matéria observável para hipóteses.', ('corpus local', 'exemplo de uso', 'marca'), 'Dados precisam preservar contexto e origem.', 'metalinguagem', ('uma frase registrada com contexto',), ('Não é interpretação pronta.',)),
    ConceitoPortugues(707, 'observação linguística', 'Observação linguística é descrição inicial do que aparece nos dados antes de explicar por quê.', 'Separa ocorrência e hipótese.', ('dado linguístico', 'descrição linguística'), '', 'metalinguagem', ('esta forma aparece antes do nome em cinco casos',), ('Não é causa nem regra definitiva.',)),
    ConceitoPortugues(708, 'análise fonológica', 'Análise fonológica reconstrói unidades e oposições sonoras relevantes num sistema definido.', 'Aplica fonema, sílaba, prosódia e processos.', ('fonema', 'oposição fonológica', 'fonotática'), 'Precisa de inventário por variedade.', 'metalinguagem', ('comparar pares e posições sonoras',), ('Não é transcrição fonética completa.',)),
    ConceitoPortugues(709, 'análise morfológica', 'Análise morfológica segmenta e relaciona base, morfemas, flexão e formação de palavra.', 'Aplica o conhecimento da estrutura da palavra.', ('morfema', 'base lexical', 'flexão', 'derivação'), 'Segmentações concorrentes precisam ser registradas.', 'metalinguagem', ('in-feliz-mente',), ('Não é separar letras arbitrariamente.',)),
    ConceitoPortugues(710, 'análise sintática', 'Análise sintática identifica constituintes, núcleos, dependências, funções e relações oracionais.', 'Aplica o conhecimento estrutural da frase.', ('constituinte sintático', 'núcleo sintático', 'dependente sintático', 'oração'), 'O motor automático ainda cobre apenas parte dessas operações.', 'metalinguagem', ('identificar sujeito, verbo e complemento',), ('Não é apenas nomear classes de palavras.',)),
    ConceitoPortugues(711, 'análise pragmática', 'Análise pragmática examina o que uma forma faz numa situação comunicativa e quais inferências o contexto sustenta.', 'Aplica atos de fala, dêixis, cortesia e implicatura.', ('pragmática', 'ato de fala', 'contexto', 'implicatura'), 'Sem contexto suficiente, deve retornar indeterminação.', 'metalinguagem', ('pedido indireto em situação documentada',), ('Não é leitura psicológica do falante.',)),
    ConceitoPortugues(712, 'análise textual', 'Análise textual examina coesão, coerência, estrutura, gênero, progressão e vozes num texto.', 'Integra níveis linguísticos acima da frase.', ('texto', 'macroestrutura textual', 'microestrutura textual', 'gênero textual'), 'Critérios dependem do objetivo de análise.', 'metalinguagem', ('mapear tese, conectivos e retomadas',), ('Não é resumo por necessidade.',)),
    ConceitoPortugues(713, 'anotação linguística', 'Anotação linguística associa marcas explícitas a unidades de dado segundo um esquema definido.', 'Permite tornar análises comparáveis e testáveis.', ('dado linguístico', 'marca'), 'O esquema precisa documentar categorias e incerteza.', 'metalinguagem', ('marcar palavra como verbo com justificativa',), ('Anotação não transforma hipótese em fato.',)),
    ConceitoPortugues(714, 'segmentação de corpus', 'Segmentação de corpus divide dados em documentos, frases, tokens ou outras unidades preservando rastreabilidade.', 'Prepara análise sem perder origem.', ('corpus local', 'segmentação gráfica', 'dado linguístico'), 'Unidades de fala exigem critérios prosódicos próprios.', 'metalinguagem', ('documento → frases → tokens',), ('Não é apagar contexto.',)),
    ConceitoPortugues(715, 'classificação linguística', 'Classificação linguística atribui categoria a uma unidade com critérios, evidência e possibilidade de revisão.', 'Organiza análise sem fingir certeza absoluta.', ('classe gramatical', 'anotação linguística', 'critério'), 'Categorias podem sobrepor-se conforme nível e uso.', 'metalinguagem', ('classificar “claro” como adjetivo ou advérbio conforme construção',), ('Não é rotulagem sem contexto.',)),
    ConceitoPortugues(716, 'carta', 'Carta é gênero dirigido a destinatário, organizado por situação de comunicação, abertura, corpo e fechamento variáveis.', 'Permite analisar voz, destinatário e finalidade.', ('gênero textual', 'destinatário', 'texto'), 'Convenções variam entre carta pessoal, formal e histórica.', 'texto_discurso', ('carta pessoal ou formal',), ('Não é formato único obrigatório.',)),
    ConceitoPortugues(717, 'correio eletrónico', 'Correio eletrónico é gênero digital de mensagem com destinatário, assunto, corpo e metadados de envio.', 'Relaciona escrita, registro e comunicação assíncrona.', ('gênero digital', 'destinatário', 'registro'), 'Convenções mudam por ambiente e finalidade.', 'texto_discurso', ('mensagem de trabalho por email',), ('Não é sinónimo de carta em todos os usos.',)),
    ConceitoPortugues(718, 'aviso', 'Aviso é gênero breve que informa, alerta ou orienta um público sobre situação específica.', 'Exige clareza, destinatário e ação relevante.', ('gênero textual', 'intenção comunicativa', 'concisão'), '', 'texto_discurso', ('Aviso: porta fechada.',), ('Não é notícia detalhada.',)),
    ConceitoPortugues(719, 'notícia', 'Notícia é gênero informativo que apresenta acontecimento considerado relevante com identificação de fontes, tempo, lugar e participantes quando disponíveis.', 'Organiza informação factual e atribuição.', ('gênero informativo', 'evidência', 'referência'), 'A veracidade depende de apuração externa; o PSF não deve inventar fatos.', 'texto_discurso', ('texto jornalístico sobre acontecimento verificado',), ('Não é opinião disfarçada.',)),
    ConceitoPortugues(720, 'reportagem', 'Reportagem é gênero informativo ampliado que investiga tema ou acontecimento por múltiplas fontes, contexto e descrição.', 'Aprofunda informação além do anúncio inicial.', ('notícia', 'pesquisa', 'citação'), 'Exige fontes externas verificáveis quando trata do mundo.', 'texto_discurso', ('reportagem com entrevistas e dados',), ('Não é simples notícia longa.',)),
    ConceitoPortugues(721, 'entrevista', 'Entrevista é gênero organizado por interação entre quem pergunta e quem responde, com finalidade e contexto definidos.', 'Permite analisar turnos, perguntas, respostas e edição.', ('diálogo', 'turno de fala', 'intenção comunicativa'), 'A edição pode alterar ordem e extensão; deve ser declarada.', 'texto_discurso', ('pergunta seguida de resposta registrada',), ('Não transforma resposta em verdade automática.',)),
    ConceitoPortugues(722, 'artigo de opinião', 'Artigo de opinião é gênero em que uma voz defende tese sobre tema público por argumentos identificáveis.', 'Integra tese, evidência, contra-argumento e estilo autoral.', ('argumentação', 'tese', 'gênero textual'), '', 'texto_discurso', ('texto que defende uma posição',), ('Opinião não dispensa justificativa.',)),
    ConceitoPortugues(723, 'ensaio', 'Ensaio é gênero reflexivo que explora uma questão por argumentação, interpretação e voz autoral, podendo manter abertura.', 'Permite investigação escrita sem exigir formato experimental único.', ('argumentação', 'interpretação', 'estilo'), 'Convenções dependem do contexto académico ou literário.', 'texto_discurso', ('ensaio sobre linguagem',), ('Não é ausência de rigor.',)),
    ConceitoPortugues(724, 'requerimento', 'Requerimento é gênero formal pelo qual alguém solicita providência a uma autoridade ou instituição identificada.', 'Organiza destinatário, pedido, fundamento e identificação.', ('gênero formal', 'ato diretivo', 'destinatário'), 'Exigências legais e administrativas precisam ser verificadas externamente.', 'texto_discurso', ('pedido formal documentado',), ('Não garante deferimento.',)),
    ConceitoPortugues(725, 'instrução procedural', 'Instrução procedural é texto que ordena ações para alcançar resultado ou executar tarefa.', 'Exige sequência, condições e critérios de conclusão.', ('instrução', 'relação de sequência', 'clareza'), '', 'texto_discurso', ('abra o ficheiro; execute o teste; verifique o resultado',), ('Não é descrição do que já aconteceu.',)),
    ConceitoPortugues(726, 'receita textual', 'Receita textual é gênero procedural que relaciona materiais, quantidades e passos para produzir um resultado.', 'Materializa instrução com dependências e ordem.', ('instrução procedural', 'quantificação', 'relação de sequência'), 'Conteúdo culinário ou técnico específico precisa ser validado no domínio.', 'texto_discurso', ('ingredientes e modo de preparo',), ('Não é prova científica do resultado.',)),
    ConceitoPortugues(727, 'poema', 'Poema é gênero verbal organizado por escolhas de ritmo, imagem, som, disposição e condensação de sentido, com grande variação formal.', 'Permite analisar função estética sem exigir uma forma única.', ('gênero literário', 'ritmo', 'figura de linguagem'), 'Interpretação poética permanece aberta a leituras justificadas.', 'texto_discurso', ('texto em versos ou prosa poética',), ('Poema não é definido apenas por rima.',)),
