    ConceitoPortugues(1058, 'argumento de autoridade documentada', 'argumento que usa fonte identificada sem torná-la infalível', 'Permite reconhecer, explicar e testar argumento de autoridade documentada na construção do Português.', ('texto',), '', 'texto_discurso', ('o estudo citado fornece evidência verificável',), ()),
    ConceitoPortugues(1059, 'falácia de generalização precipitada', 'erro de concluir regra ampla com poucos casos', 'Permite reconhecer, explicar e testar falácia de generalização precipitada na construção do Português.', ('texto',), '', 'texto_discurso', ('dois exemplos não provam todos os usos',), ()),
    ConceitoPortugues(1060, 'falácia de falsa causa', 'erro de tratar sequência ou correlação como causa suficiente', 'Permite reconhecer, explicar e testar falácia de falsa causa na construção do Português.', ('texto',), '', 'texto_discurso', ('aconteceu depois, logo foi causado por isso',), ()),
    ConceitoPortugues(1061, 'falácia de falso dilema', 'erro de apresentar apenas duas opções quando há outras', 'Permite reconhecer, explicar e testar falácia de falso dilema na construção do Português.', ('texto',), '', 'texto_discurso', ('ou aceita tudo ou rejeita tudo',), ()),
    ConceitoPortugues(1062, 'falácia ad hominem', 'erro de atacar pessoa em vez do argumento', 'Permite reconhecer, explicar e testar falácia ad hominem na construção do Português.', ('texto',), '', 'texto_discurso', ('desqualificar o autor sem analisar a prova',), ()),
    ConceitoPortugues(1063, 'falácia de circularidade', 'erro de usar conclusão como premissa', 'Permite reconhecer, explicar e testar falácia de circularidade na construção do Português.', ('texto',), '', 'texto_discurso', ('é verdadeiro porque é verdade',), ()),
    ConceitoPortugues(1064, 'narração em primeira pessoa', 'narração feita por voz participante marcada por primeira pessoa', 'Permite reconhecer, explicar e testar narração em primeira pessoa na construção do Português.', ('texto',), '', 'texto_discurso', ('Eu entrei e observei.',), ()),
    ConceitoPortugues(1065, 'narração em terceira pessoa', 'narração feita por voz externa em terceira pessoa', 'Permite reconhecer, explicar e testar narração em terceira pessoa na construção do Português.', ('texto',), '', 'texto_discurso', ('Ela entrou e observou.',), ()),
    ConceitoPortugues(1066, 'narrador participante', 'narrador que atua na história', 'Permite reconhecer, explicar e testar narrador participante na construção do Português.', ('texto',), '', 'texto_discurso', ('um personagem conta o que viveu',), ()),
    ConceitoPortugues(1067, 'narrador observador', 'narrador que relata sem acesso total ao interior das personagens', 'Permite reconhecer, explicar e testar narrador observador na construção do Português.', ('texto',), '', 'texto_discurso', ('descreve ações visíveis',), ()),
    ConceitoPortugues(1068, 'narrador omnisciente', 'narrador que apresenta conhecimento amplo de personagens e eventos', 'Permite reconhecer, explicar e testar narrador omnisciente na construção do Português.', ('texto',), '', 'texto_discurso', ('revela pensamentos de várias personagens',), ()),
    ConceitoPortugues(1069, 'focalização interna', 'perspetiva limitada ao conhecimento de personagem', 'Permite reconhecer, explicar e testar focalização interna na construção do Português.', ('texto',), '', 'texto_discurso', ('o leitor sabe apenas o que Ana percebe',), ()),
    ConceitoPortugues(1070, 'focalização externa', 'perspetiva limitada ao observável', 'Permite reconhecer, explicar e testar focalização externa na construção do Português.', ('texto',), '', 'texto_discurso', ('o texto mostra gestos sem pensamentos',), ()),
    ConceitoPortugues(1071, 'focalização zero', 'perspetiva narrativa sem limitação estável a personagem', 'Permite reconhecer, explicar e testar focalização zero na construção do Português.', ('texto',), '', 'texto_discurso', ('o narrador conhece vários interiores',), ()),
    ConceitoPortugues(1072, 'tempo cronológico', 'ordem temporal linear dos acontecimentos', 'Permite reconhecer, explicar e testar tempo cronológico na construção do Português.', ('texto',), '', 'texto_discurso', ('primeiro chegou, depois falou',), ()),
    ConceitoPortugues(1073, 'tempo psicológico', 'organização temporal pela experiência subjetiva', 'Permite reconhecer, explicar e testar tempo psicológico na construção do Português.', ('texto',), '', 'texto_discurso', ('um instante evoca longa memória',), ()),
    ConceitoPortugues(1074, 'analepse', 'retorno narrativo a evento anterior', 'Permite reconhecer, explicar e testar analepse na construção do Português.', ('texto',), '', 'texto_discurso', ('o capítulo relembra a infância',), ()),
    ConceitoPortugues(1075, 'variação fonética', 'diferença de realização sonora sem mudança necessária de estrutura gramatical', 'Permite reconhecer, explicar e testar variação fonética na construção do Português.', ('análise linguística',), '', 'metalinguagem', ('r pode ter realizações regionais',), ()),
    ConceitoPortugues(1076, 'variação fonológica', 'diferença sistemática no inventário ou distribuição de contrastes', 'Permite reconhecer, explicar e testar variação fonológica na construção do Português.', ('análise linguística',), '', 'metalinguagem', ('certas variedades distinguem realizações em contextos diferentes',), ()),
    ConceitoPortugues(1077, 'variação morfológica', 'diferença de formas flexionais ou derivacionais entre usos', 'Permite reconhecer, explicar e testar variação morfológica na construção do Português.', ('análise linguística',), '', 'metalinguagem', ('formas participiais podem variar',), ()),
    ConceitoPortugues(1078, 'variação sintática', 'diferença de construção e ordem entre variedades', 'Permite reconhecer, explicar e testar variação sintática na construção do Português.', ('análise linguística',), '', 'metalinguagem', ('posição de clítico pode variar',), ()),
    ConceitoPortugues(1079, 'variação lexical', 'diferença de palavras para referente ou situação semelhante', 'Permite reconhecer, explicar e testar variação lexical na construção do Português.', ('análise linguística',), '', 'metalinguagem', ('autocarro e ônibus',), ()),
    ConceitoPortugues(1080, 'variação semântica', 'diferença de sentido associado à mesma forma entre comunidades', 'Permite reconhecer, explicar e testar variação semântica na construção do Português.', ('análise linguística',), '', 'metalinguagem', ('rapariga tem avaliações diferentes por variedade',), ()),
    ConceitoPortugues(1081, 'variação pragmática', 'diferença de estratégias de uso e cortesia', 'Permite reconhecer, explicar e testar variação pragmática na construção do Português.', ('análise linguística',), '', 'metalinguagem', ('formas de tratamento variam por comunidade',), ()),
    ConceitoPortugues(1082, 'mudança fonética', 'alteração histórica na realização de sons', 'Permite reconhecer, explicar e testar mudança fonética na construção do Português.', ('análise linguística',), '', 'metalinguagem', ('um segmento pode enfraquecer ao longo do tempo',), ()),
    ConceitoPortugues(1083, 'mudança fonológica', 'alteração histórica de contrastes sonoros', 'Permite reconhecer, explicar e testar mudança fonológica na construção do Português.', ('análise linguística',), '', 'metalinguagem', ('dois fonemas podem fundir-se',), ()),
    ConceitoPortugues(1084, 'mudança morfológica', 'alteração histórica em paradigmas e formação de palavras', 'Permite reconhecer, explicar e testar mudança morfológica na construção do Português.', ('análise linguística',), '', 'metalinguagem', ('uma flexão pode regularizar-se',), ()),
    ConceitoPortugues(1085, 'mudança sintática', 'alteração histórica em ordem ou construção', 'Permite reconhecer, explicar e testar mudança sintática na construção do Português.', ('análise linguística',), '', 'metalinguagem', ('uma posição pronominal pode tornar-se mais frequente',), ()),
    ConceitoPortugues(1086, 'mudança semântica', 'alteração histórica de sentido', 'Permite reconhecer, explicar e testar mudança semântica na construção do Português.', ('análise linguística',), '', 'metalinguagem', ('uma palavra pode ampliar ou restringir significado',), ()),
    ConceitoPortugues(1087, 'ampliação semântica', 'mudança em que termo passa a cobrir domínio maior', 'Permite reconhecer, explicar e testar ampliação semântica na construção do Português.', ('análise linguística',), '', 'metalinguagem', ('uma palavra específica ganha uso geral',), ()),
    ConceitoPortugues(1088, 'restrição semântica', 'mudança em que termo passa a cobrir domínio menor', 'Permite reconhecer, explicar e testar restrição semântica na construção do Português.', ('análise linguística',), '', 'metalinguagem', ('uma palavra geral torna-se especializada',), ()),
    ConceitoPortugues(1089, 'melhoria semântica', 'mudança para avaliação social mais positiva', 'Permite reconhecer, explicar e testar melhoria semântica na construção do Português.', ('análise linguística',), '', 'metalinguagem', ('termo adquire valor favorável',), ()),
    ConceitoPortugues(1090, 'pejorização', 'mudança para avaliação social mais negativa', 'Permite reconhecer, explicar e testar pejorização na construção do Português.', ('análise linguística',), '', 'metalinguagem', ('termo adquire valor depreciativo',), ()),
    ConceitoPortugues(1091, 'dialetologia', 'estudo sistemático da distribuição geográfica de variedades', 'Permite reconhecer, explicar e testar dialetologia na construção do Português.', ('análise linguística',), '', 'metalinguagem', ('mapear formas por regiões',), ()),
    ConceitoPortugues(1092, 'geolinguística', 'estudo espacial de fenómenos linguísticos', 'Permite reconhecer, explicar e testar geolinguística na construção do Português.', ('análise linguística',), '', 'metalinguagem', ('atlas de variantes regionais',), ()),
    ConceitoPortugues(1093, 'planeamento linguístico', 'ação organizada sobre estatuto, ensino ou forma de língua', 'Permite reconhecer, explicar e testar planeamento linguístico na construção do Português.', ('análise linguística',), '', 'metalinguagem', ('definir política de ensino linguístico',), ()),
    ConceitoPortugues(1094, 'política linguística', 'decisões sociais e institucionais sobre línguas e variedades', 'Permite reconhecer, explicar e testar política linguística na construção do Português.', ('análise linguística',), '', 'metalinguagem', ('reconhecer línguas em educação',), ()),
    ConceitoPortugues(1095, 'consciência metalinguística', 'capacidade de refletir explicitamente sobre a língua', 'Permite reconhecer, explicar e testar consciência metalinguística na construção do Português.', ('análise linguística',), '', 'metalinguagem', ('explicar por que uma forma funciona',), ()),
    ConceitoPortugues(1096, 'lacuna interna', 'ausência de definição, dependência, exemplo ou teste necessário dentro do conhecimento declarado', 'Permite reconhecer, explicar e testar lacuna interna na construção do Português.', ('análise linguística',), '', 'metalinguagem', ('conceito sem base seria lacuna interna',), ()),
    ConceitoPortugues(1097, 'fronteira aberta', 'limite que depende de dados vivos, variedade, contexto ou investigação externa', 'Permite reconhecer, explicar e testar fronteira aberta na construção do Português.', ('análise linguística',), '', 'metalinguagem', ('pronúncia regional exige observação local',), ()),
    ConceitoPortugues(1098, 'limite operacional', 'capacidade que o motor ainda não executa embora o conceito esteja construído', 'Permite reconhecer, explicar e testar limite operacional na construção do Português.', ('análise linguística',), '', 'metalinguagem', ('o motor conhece elipse mas pode não recuperá-la automaticamente',), ()),
    ConceitoPortugues(1099, 'mestria conceitual', 'estado em que o domínio interno possui definição, dependências, exemplos, contraste e testes sem lacunas internas', 'Permite reconhecer, explicar e testar mestria conceitual na construção do Português.', ('análise linguística',), '', 'metalinguagem', ('a base pode explicar cada conceito sem saltar dependências',), ()),
    ConceitoPortugues(1100, 'hibridismo', 'Hibridismo é processo de formação de palavras que combina radicais ou afixos de línguas diferentes numa mesma palavra.', 'Explica por que palavras como sociologia (latim + grego) e automóvel (grego + latim) não se encaixam só em justaposição ou aglutinação de uma língua só.', ('justaposição', 'aglutinação'), '', 'morfologia_lexico', ('sociologia', 'automóvel', 'burocracia'), ()),
    ConceitoPortugues(1101, 'verbo pronominal', 'Verbo pronominal é o verbo que exige um pronome reflexivo como parte obrigatória da sua forma, mesmo quando o sentido não é reflexivo.', 'Separa verbos como arrepender-se e queixar-se, que não existem sem o pronome, de verbos que só ocasionalmente recebem pronome reflexivo.', ('verbo', 'pronome reflexivo'), '', 'morfologia_lexico', ('arrepender-se', 'queixar-se', 'suicidar-se'), ()),
    ConceitoPortugues(1102, 'verbo reflexivo', 'Verbo reflexivo é o verbo pronominal cuja ação, praticada pelo sujeito, recai sobre o próprio sujeito.', 'Distingue eu me machuquei (ação sobre si mesmo) de eu me arrependi (verbo pronominal sem ação transferível a devolver ao sujeito).', ('verbo pronominal',), '', 'morfologia_lexico', ('machucar-se', 'pentear-se', 'vestir-se'), ()),
    ConceitoPortugues(1103, 'verbo impessoal', 'Verbo impessoal é o verbo usado sem sujeito gramatical algum, nem mesmo oculto ou indeterminado.', 'Explica orações sem sujeito como chove e há problemas, onde não existe nada, explícito ou implícito, praticando a ação.', ('verbo', 'oração sem sujeito'), '', 'morfologia_lexico', ('chove', 'há problemas', 'faz frio'), ()),
    ConceitoPortugues(1104, 'verbo unipessoal', 'Verbo unipessoal é o verbo conjugado só na terceira pessoa, geralmente para vozes de animais ou fenômenos específicos, mas que admite sujeito — diferente do impessoal.', 'Separa o cão late (tem sujeito, só não conjuga em todas as pessoas) do impessoal chove (nunca tem sujeito nenhum).', ('verbo', 'pessoa gramatical'), '', 'morfologia_lexico', ('o cão late', 'a vaca muge'), ()),
    ConceitoPortugues(1105, 'verbo anômalo', 'Verbo anômalo é o verbo irregular cuja conjugação muda de radical entre tempos, a ponto de parecer formada por mais de um verbo (supleção).', 'Identifica ser e ir como o caso mais extremo de irregularidade: fui serve tanto para ser quanto para ir, e são/eram não têm nenhuma semelhança sonora com a forma ser.', ('verbo irregular',), '', 'morfologia_lexico', ('ser', 'ir'), ()),
    ConceitoPortugues(1106, 'locução verbal', 'Locução verbal é o nome tradicional escolar para a combinação de um verbo auxiliar com um verbo principal no infinitivo, gerúndio ou particípio — o mesmo fenômeno que a linguística chama perífrase verbal.', 'Reconhece vai chover, está chovendo e tinha chovido como uma única unidade verbal, não dois verbos separados.', ('verbo auxiliar', 'perífrase verbal'), '', 'discurso_e_interpretacao', ('vai chover', 'está chovendo', 'tinha chovido'), ()),
    ConceitoPortugues(1107, 'regência nominal', 'Regência nominal é a relação de dependência entre um nome (substantivo, adjetivo ou advérbio) e o termo que ele exige, geralmente ligado por uma preposição fixa.', 'Separa a regência do nome (respeito a, orgulho de) da regência do verbo, embora ambas usem preposição para ligar termos.', ('regência',), '', 'sintaxe_e_uso', ('respeito a', 'orgulho de', 'necessário a'), ()),
    ConceitoPortugues(1108, 'se apassivador', 'Se apassivador é o pronome se que transforma um verbo transitivo direto em voz passiva sintética, com o objeto virando o sujeito paciente que concorda em número com o verbo.', 'Explica por que explicam-se os problemas equivale a os problemas são explicados, com o verbo no plural concordando com problemas, não com um sujeito oculto indeterminado.', ('voz passiva', 'pronome reflexivo', 'verbo transitivo direto'), '', 'sintaxe', ('explicam-se os problemas', 'explica-se o problema'), ()),
    ConceitoPortugues(1109, 'se índice de indeterminação do sujeito', 'Se índice de indeterminação do sujeito é o pronome se junto a um verbo intransitivo, de ligação ou transitivo indireto, que nunca concorda em número porque não há sujeito nenhum para concordância.', 'Explica por que entende-se de livros e precisa-se de funcionários mantêm o verbo sempre na terceira pessoa do singular, mesmo com um plural depois da preposição.', ('sujeito indeterminado', 'pronome reflexivo'), '', 'sintaxe', ('entende-se de livros', 'precisa-se de funcionários'), ()),
    ConceitoPortugues(1110, 'sinestesia', 'Sinestesia é figura que combina impressões de sentidos diferentes numa mesma expressão.', 'Explica combinações como cor quente e silêncio ensurdecedor, que misturam visão/tato ou som/ausência de som.', ('metáfora', 'conotação'), '', 'papeis_e_figuras', ('cor quente', 'voz doce', 'silêncio ensurdecedor'), ()),
    ConceitoPortugues(1111, 'antonomásia', 'Antonomásia substitui um nome próprio por uma expressão que o caracteriza, ou vice-versa.', 'Explica por que a Cidade Maravilhosa identifica o Rio de Janeiro sem citar o nome, do mesmo jeito que metonímia substitui um termo por outro relacionado.', ('metonímia',), '', 'papeis_e_figuras', ('a Cidade Maravilhosa', 'o Poeta dos Escravos'), ()),
    ConceitoPortugues(1112, 'zeugma', 'Zeugma é a elipse de um termo já expresso numa oração anterior, omitido numa oração coordenada seguinte.', 'Explica eu gosto de música; ele, de esportes, em que gosta fica implícito na segunda oração.', ('elipse', 'oração coordenada'), '', 'papeis_e_figuras', ('Eu gosto de música; ele, de esportes.',), ()),
    ConceitoPortugues(1113, 'assíndeto', 'Assíndeto é a figura de encadear orações coordenadas sem conjunção, ligadas só por vírgula, para dar ritmo rápido à frase.', 'Nomeia o efeito estilístico do mesmo fenômeno que oração coordenada assindética já constrói — vim, vi, venci.', ('oração coordenada assindética',), '', 'papeis_e_figuras', ('Vim, vi, venci.',), ()),
    ConceitoPortugues(1114, 'polissíndeto', 'Polissíndeto é a figura de repetir a mesma conjunção antes de cada oração coordenada, para dar ênfase ou acúmulo.', 'Nomeia o efeito estilístico oposto ao assíndeto, usando oração coordenada sindética repetida em vez de omitida.', ('oração coordenada sindética', 'coordenação aditiva'), '', 'papeis_e_figuras', ('E corre, e pula, e grita.',), ()),
    ConceitoPortugues(1115, 'aliteração', 'Aliteração é a repetição do mesmo som consonantal no início de palavras próximas, para efeito sonoro.', 'Reconhecida de verdade contando a consoante inicial mais frequente numa sequência de palavras, não citada de memória — o rato roeu a roupa do rei de Roma repete o r cinco vezes.', ('consoante', 'som'), '', 'papeis_e_figuras', ('o rato roeu a roupa do rei de Roma',), ()),
    ConceitoPortugues(1116, 'assonância', 'Assonância é a repetição do mesmo som vocálico em palavras próximas, para efeito sonoro.', 'Reconhecida de verdade contando a vogal inicial mais frequente numa sequência de palavras — Amanhã a Ana anda apressada repete o som de a cinco vezes.', ('vogal', 'som'), '', 'papeis_e_figuras', ('Amanhã a Ana anda apressada.',), ()),
    ConceitoPortugues(1117, 'paronomásia', 'Paronomásia é o jogo de palavras que aproxima parônimos (palavras parecidas no som, diferentes no sentido) para efeito expressivo.', 'Reaproveita paronímia já construída: quem não arrisca, não petisca aproxima arrisca e petisca pelo som.', ('paronímia',), '', 'papeis_e_figuras', ('Quem não arrisca, não petisca.',), ()),
    ConceitoPortugues(1118, 'silepse', 'Silepse é a concordância feita com a ideia (sentido) em vez da forma gramatical explícita.', 'Explica Vossa Excelência está cansado, em que o adjetivo concorda com o gênero da pessoa real, não com a forma gramatical feminina de vossa excelência.', ('concordância nominal', 'concordância verbal'), '', 'papeis_e_figuras', ('Vossa Excelência está cansado.',), ()),
    ConceitoPortugues(1119, 'anacoluto', 'Anacoluto é a quebra da construção sintática iniciada numa oração, abandonada por outra estrutura antes de terminar.', 'Explica eu, esse problema não me interessa, em que eu começa como se fosse sujeito mas a oração muda de estrutura sem ele.', ('oração',), '', 'papeis_e_figuras', ('Eu, esse problema não me interessa.',), ()),
    ConceitoPortugues(1120, 'trema', 'Trema é o sinal gráfico de dois pontos sobre o u, abolido do português padrão pelo Acordo Ortográfico de 1990, mas preservado em nomes próprios estrangeiros e suas derivações.', 'Explica por que Müller e Hülsmann mantêm o trema mesmo depois do acordo, que só eliminou seu uso em palavras genuinamente portuguesas como linguiça e sequência.', ('acento', 'marca'), '', 'som_e_escrita', ('Müller', 'Hülsmann'), ()),
    ConceitoPortugues(1121, 'paródia', 'Paródia é a reescrita de um texto conhecido que transforma seu sentido ou tom, geralmente para efeito cômico ou crítico, mantendo referência reconhecível ao original.', 'Liga intertextualidade a um caso concreto: uma paródia só existe porque aponta de volta para o texto que imita e altera.', ('intertextualidade',), '', 'texto_discurso', ('uma letra de música reescrita com sentido cômico sobre outro tema',), ()),
    ConceitoPortugues(1122, 'pastiche', 'Pastiche é a imitação do estilo de um autor ou obra, sem necessariamente alterar o sentido ou ter intenção cômica ou crítica — ao contrário da paródia.', 'Distingue pastiche de paródia pela intenção: pastiche imita por admiração ou exercício de estilo, paródia imita para transformar ou criticar.', ('paródia', 'intertextualidade'), '', 'texto_discurso', ('um conto escrito imitando o estilo de outro autor, sem sátira nem crítica',), ()),
    ConceitoPortugues(1123, 'sátira', 'Sátira é o texto que usa ironia, exagero ou humor para criticar costumes, pessoas públicas ou instituições.', 'Liga ironia e hipérbole a um gênero concreto: a sátira exagera e ironiza deliberadamente para expor uma crítica.', ('ironia', 'hipérbole'), '', 'texto_discurso', ('uma charge política que exagera um defeito de um governante',), ()),
    ConceitoPortugues(1124, 'verso', 'Verso é cada linha de um poema, unidade rítmica organizada por contagem de sílabas e por rima.', 'Serve de base para estrofe, métrica e rima.', ('sílaba',), '', 'papeis_e_figuras', ('Amor é fogo que arde sem se ver',), ()),
    ConceitoPortugues(1125, 'estrofe', 'Estrofe é o agrupamento de versos separado por espaço em branco, unidade maior que o verso dentro do poema.', 'Organiza versos em blocos, do mesmo jeito que parágrafos organizam frases em prosa.', ('verso',), '', 'papeis_e_figuras', ('quatro versos formando uma quadra',), ()),
    ConceitoPortugues(1126, 'métrica', 'Métrica é o estudo da contagem de sílabas poéticas de um verso e da organização rítmica que essa contagem produz.', 'Não é a contagem gramatical de sílabas: a métrica poética funde vogais de palavras vizinhas (sinalefa) quando uma palavra termina e a seguinte começa em vogal. A contagem automática com sinalefa ainda não está construída; depende da tonicidade automática, já registrada como fronteira aberta em sílaba tônica.', ('sílaba', 'verso'), '', 'papeis_e_figuras', ('contar as sílabas poéticas de um verso decassílabo dá dez',), ()),
    ConceitoPortugues(1127, 'escansão', 'Escansão é o processo de contar e marcar as sílabas poéticas de um verso, aplicando sinalefa nas junções entre palavras.', 'É o procedimento concreto que a métrica descreve; automatizá-lo depende da mesma contagem de sílabas poéticas ainda não construída, registrada em métrica.', ('métrica',), '', 'papeis_e_figuras', ('separar um verso em sílabas poéticas contadas uma a uma',), ()),
