    ConceitoPortugues(1131, 'rima toante', 'Rima toante é a coincidência apenas do som da vogal tônica final entre versos, sem exigir que as consoantes seguintes também coincidam.', 'Separa a rima mais solta, de som aproximado, da rima consoante, de som completo.', ('rima silábica',), '', 'papeis_e_figuras', ('coração / paixão (mesma vogal tônica, consoantes finais diferentes)',), ()),
