class ConstrutorConhecimentoPortugues:
    """Acesso único ao conhecimento puro de Português."""

    def __init__(self, conceitos: tuple[ConceitoPortugues, ...] | None = None) -> None:
        self._conceitos = conceitos or CONCEITOS_PORTUGUES_PURO
        self._por_nome = {conceito.nome.casefold(): conceito for conceito in self._conceitos}
        self._por_nome_normalizado = {
            _normalizar_chave(conceito.nome): conceito for conceito in self._conceitos
        }
        self._aliases = {alias.casefold(): alvo.casefold() for alias, alvo in ALIASES_CONCEITOS_PORTUGUES.items()}
        self._aliases_normalizados = {
            _normalizar_chave(alias): _normalizar_chave(alvo)
            for alias, alvo in ALIASES_CONCEITOS_PORTUGUES.items()
        }

    def todos(self) -> tuple[ConceitoPortugues, ...]:
        return self._conceitos

    def nomes(self) -> tuple[str, ...]:
        return tuple(conceito.nome for conceito in self._conceitos)

    def buscar(self, nome: str) -> ConceitoPortugues | None:
        chave = str(nome).casefold().strip()
        chave = self._aliases.get(chave, chave)
        conceito = self._por_nome.get(chave)
        if conceito is not None:
            return conceito

        chave_norm = _normalizar_chave(chave)
        chave_norm = self._aliases_normalizados.get(chave_norm, chave_norm)
        conceito = self._por_nome_normalizado.get(chave_norm)
        if conceito is not None:
            return conceito

        for sufixo, rep in (
            ("oes", "ao"),
            ("aes", "ao"),
            ("ais", "al"),
            ("eis", "el"),
            ("ois", "ol"),
            ("es", ""),
            ("s", ""),
            ("ns", "m"),
        ):
            if chave_norm.endswith(sufixo):
                candidato = chave_norm[: -len(sufixo)] + rep
                conceito = self._por_nome_normalizado.get(candidato)
                if conceito is not None:
                    return conceito

        return None

    def aliases(self) -> dict[str, str]:
        """Equivalências terminológicas que apontam para um conceito canónico."""
        return dict(ALIASES_CONCEITOS_PORTUGUES)

    def buscar_texto(self, trecho: str) -> tuple[ConceitoPortugues, ...]:
        alvo = str(trecho).casefold().strip()
        if not alvo:
            return ()
        alias_alvo = self._aliases.get(alvo)
        encontrados = [
            conceito for conceito in self._conceitos
            if alvo in conceito.nome.casefold()
            or alvo in conceito.construcao.casefold()
            or alvo in conceito.funcao.casefold()
        ]
        if alias_alvo and alias_alvo in self._por_nome:
            conceito = self._por_nome[alias_alvo]
            if conceito not in encontrados:
                encontrados.append(conceito)
        return tuple(encontrados)

    def caminho_natural(self) -> tuple[str, ...]:
        return tuple(conceito.nome for conceito in self._conceitos)

    def trilho_ate(self, nome: str) -> tuple[str, ...]:
        alvo = self.buscar(nome)
        if alvo is None:
            return ()
        return tuple(conceito.nome for conceito in self._conceitos if conceito.ordem <= alvo.ordem)

    def dependencias_de(self, nome: str) -> tuple[str, ...]:
        conceito = self.buscar(nome)
        return () if conceito is None else conceito.depende_de

    def dependencias_transitivas_de(self, nome: str) -> tuple[str, ...]:
        alvo = self.buscar(nome)
        if alvo is None:
            return ()
        resultado: list[str] = []
        vistos: set[str] = set()

        def visitar(atual: ConceitoPortugues) -> None:
            for dependencia in atual.depende_de:
                if dependencia in vistos:
                    continue
                conceito = self.buscar(dependencia)
                if conceito is None:
                    continue
                visitar(conceito)
                vistos.add(dependencia)
                resultado.append(dependencia)

        visitar(alvo)
        return tuple(resultado)

    def temas_consulta(self) -> tuple[str, ...]:
        vistas: list[str] = []
        for conceito in self._conceitos:
            if conceito.tema_consulta not in vistas:
                vistas.append(conceito.tema_consulta)
        return tuple(vistas)

    def por_tema(self, tema: str) -> tuple[ConceitoPortugues, ...]:
        """Consulta temática; não define ordem, verdade ou dependência."""
        alvo = str(tema).casefold().strip()
        return tuple(c for c in self._conceitos if c.tema_consulta.casefold() == alvo)

    def camadas(self) -> tuple[str, ...]:
        """Compatibilidade legada. Use :meth:`temas_consulta`."""
        return self.temas_consulta()

    def por_camada(self, camada: str) -> tuple[ConceitoPortugues, ...]:
        """Compatibilidade legada. A camada não tem autoridade estrutural."""
        return self.por_tema(camada)

    def estatisticas(self) -> dict[str, int]:
        return {
            "conceitos": len(self._conceitos),
            "temas_de_consulta": len(self.temas_consulta()),
            "camadas": len(self.temas_consulta()),  # compatibilidade legada
            "conceitos_com_lacuna": sum(bool(c.lacuna) for c in self._conceitos),
            "lacunas_internas": sum(bool(c.lacuna) for c in self._conceitos),
            "fronteiras_abertas": len(FRONTEIRAS_ABERTAS_PORTUGUES),
            "limites_operacionais": len(LIMITES_OPERACIONAIS_PORTUGUES),
            "conceitos_com_exemplo": sum(bool(c.exemplos_minimos) for c in self._conceitos),
            "relacoes_de_dependencia": sum(len(c.depende_de) for c in self._conceitos),
            "aliases": len(self._aliases),
        }

    def funcionamento(self) -> tuple[str, ...]:
        return (
            "Português PSF nasce por diferença mínima, não por cópia cega de gramática externa.",
            "Som, corrente de ar, articulação, fonema, prosódia e oralidade constroem o domínio sonoro na mesma linha.",
            "Marca, grafema, alfabeto, ortografia, sílaba e acentuação constroem o domínio escrito na mesma linha.",
            "Palavra, lexema, morfema, derivação, flexão e conjugação constroem o domínio morfológico na mesma linha.",
            "Sintagma, oração, sujeito, predicado, complementos e períodos constroem a sintaxe.",
            "Sentido, referência, denotação, conotação, inferência, dêixis e pragmática constroem interpretação limitada.",
            "Texto, gênero, tipos textuais, argumentação, coesão e progressão constroem discurso.",
            "Variação, registro, adequação, leitura, escrita, fala e escuta constroem competência comunicativa.",
            "Dicionário, análise, descrição, prescrição e reconstrução PSF permitem estudar a própria língua.",
            "Ato de fala, intertextualidade, contacto linguístico, aquisição e tradução ampliam a língua sem fingir capacidades ainda não implementadas.",
            "Termos equivalentes apontam para conceitos canónicos e não criam conhecimento duplicado.",
            "Lacunas ficam marcadas; nenhuma aparência de completude substitui construção e teste.",
        )

    def lacunas(self) -> tuple[str, ...]:
        """Lacunas internas do conhecimento canónico; atualmente nenhuma conhecida."""
        return tuple(conceito.lacuna for conceito in self._conceitos if conceito.lacuna)

    def fronteiras_abertas(self) -> dict[str, str]:
        """Limites do português vivo que exigem dados, variedade ou contexto."""
        return dict(FRONTEIRAS_ABERTAS_PORTUGUES)

    def limites_operacionais(self) -> dict[str, str]:
        """Conhecimento já construído cuja automatização ainda pode ser parcial."""
        return dict(LIMITES_OPERACIONAIS_PORTUGUES)

    def mestria_conceitual(self) -> bool:
        """Confirma ausência de lacunas internas sem prometer completude absoluta."""
        return self.validar_pureza() and not self.lacunas()

    def validar_ordem(self) -> bool:
        vistos: set[str] = set()
        for conceito in self._conceitos:
            if any(dep not in vistos for dep in conceito.depende_de):
                return False
            vistos.add(conceito.nome)
        return True

    def validar_pureza(self) -> bool:
        nomes = [conceito.nome for conceito in self._conceitos]
        ordens = [conceito.ordem for conceito in self._conceitos]
        return (
            len(nomes) == len(set(nomes))
            and ordens == list(range(1, len(ordens) + 1))
            and self.validar_ordem()
            and all(c.construcao.strip() and c.funcao.strip() for c in self._conceitos)
            and self._conceitos[-1].nome == "funcionamento"
            and all(alvo in self._por_nome for alvo in self._aliases.values())
            and all(alias not in self._por_nome for alias in self._aliases)
        )
